const t="iU_woHYLpVg",e="iU_woHYLpVg",s="The Big Mistakes that Stop You from Learning English | B1 English Listening Practice Podcast",n="Coffee English",d="B1",r="Chia sẻ kinh nghiệm học",l=16,u=1108,a="auto",o=JSON.parse(`[{"start":6.64,"end":8.96,"text":"Hello English learners.","words":[["Hello",6.64],["English",7.36],["learners.",7.76]],"ipa":"/həˈloʊ ˈɪŋɡlɪʃ ˈlɝnərz/"},{"start":8.96,"end":14.48,"text":"Welcome back to Coffee English where we help you learn English the right way.","words":[["Welcome",8.96],["back",9.36],["to",9.6],["Coffee",9.92],["English",10.4],["where",11.12],["we",11.36],["help",11.52],["you",11.76],["learn",11.92],["English",12.24],["the",12.64],["right",12.88],["way.",13.12]],"ipa":"/ˈwɛlkəm bæk tu ˈkɑfi ˈɪŋɡlɪʃ wɛr wi hɛlp ju lɝn ˈɪŋɡlɪʃ ðə raɪt weɪ/"},{"start":14.48,"end":18.16,"text":"Today we are talking about something very important.","words":[["Today",14.48],["we",14.88],["are",15.12],["talking",15.36],["about",15.76],["something",16.08],["very",16.48],["important.",16.96]],"ipa":"/təˈdeɪ wi ɑr ˈtɔkɪŋ əˈbaʊt ˈsʌmθɪŋ ˈvɛri ˌɪmˈpɔrtənt/"},{"start":18.16,"end":22.08,"text":"We are not learning new words or grammar rules.","words":[["We",18.16],["are",18.4],["not",18.56],["learning",18.8],["new",19.28],["words",19.6],["or",20.08],["grammar",20.48],["rules.",20.96]],"ipa":"/wi ɑr nɑt ˈlɝnɪŋ nu wɝdz ɔr ˈɡræmər rulz/"},{"start":22.08,"end":28.96,"text":"Instead we are looking at the big mistakes that stop people from getting better at English.","words":[["Instead",22.08],["we",23.12],["are",23.44],["looking",23.6],["at",23.84],["the",24],["big",24.24],["mistakes",24.56],["that",25.12],["stop",25.52],["people",25.92],["from",26.32],["getting",26.64],["better",27.04],["at",27.36],["English.",27.68]],"ipa":"/ˌɪnˈstɛd wi ɑr ˈlʊkɪŋ æt ðə bɪɡ mɪˈsteɪks ðæt stɑp ˈpipəl frʌm ˈɡɛtɪŋ ˈbɛtər æt ˈɪŋɡlɪʃ/"},{"start":28.96,"end":34.48,"text":"These mistakes keep millions of students in the same place for years.","words":[["These",28.96],["mistakes",29.36],["keep",30],["millions",30.4],["of",30.88],["students",31.12],["in",31.6],["the",31.84],["same",32.08],["place",32.32],["for",32.64],["years.",32.96]],"ipa":"/ðiz mɪˈsteɪks kip ˈmɪljənz ʌv ˈstudənts ɪn ðə seɪm pleɪs fɔr jɪrz/"},{"start":34.48,"end":38.88,"text":"This episode will change how you think about learning English.","words":[["This",34.48],["episode",34.88],["will",35.44],["change",35.76],["how",36.16],["you",36.4],["think",36.64],["about",36.88],["learning",37.28],["English.",37.76]],"ipa":"/ðɪs ˈɛpəˌsoʊd wɪl tʃeɪndʒ haʊ ju θɪŋk əˈbaʊt ˈlɝnɪŋ ˈɪŋɡlɪʃ/"},{"start":38.88,"end":46.64,"text":"You will understand why people sometimes have trouble with English, why being perfect can hurt your progress,","words":[["You",38.88],["will",39.12],["understand",39.36],["why",39.92],["people",40.24],["sometimes",40.72],["have",41.44],["trouble",41.76],["with",42.16],["English,",42.48],["why",43.6],["being",43.84],["perfect",44.24],["can",44.8],["hurt",45.04],["your",45.36],["progress,",45.6]],"ipa":"/ju wɪl ˌʌndərˈstænd waɪ ˈpipəl səmˈtaɪmz hæv ˈtrʌbəl wɪð ˈɪŋɡlɪʃ waɪ ˈbiɪŋ pərˈfɛkt kæn hɝt jɔr ˈprɑˌɡrɛs/"},{"start":46.64,"end":55.2,"text":"and most importantly, you will learn easy ways to fix these problems and finally speak English well.","words":[["and",46.64],["most",46.88],["importantly,",47.28],["you",48.48],["will",48.72],["learn",48.96],["easy",49.36],["ways",49.76],["to",50.16],["fix",50.48],["these",50.72],["problems",51.2],["and",52.08],["finally",52.4],["speak",52.96],["English",53.36],["well.",53.92]],"ipa":"/ənd moʊst ˌɪmˈpɔrtəntli ju wɪl lɝn ˈizi weɪz tu fɪks ðiz ˈprɑbləmz ənd ˈfaɪnəli spik ˈɪŋɡlɪʃ wɛl/"},{"start":55.2,"end":61.04,"text":"After this episode, you will know the secrets of successful English learning.","words":[["After",55.2],["this",55.6],["episode,",56],["you",56.96],["will",57.2],["know",57.36],["the",57.6],["secrets",57.84],["of",58.32],["successful",58.72],["English",59.52],["learning.",59.92]],"ipa":"/ˈæftər ðɪs ˈɛpəˌsoʊd ju wɪl noʊ ðə ˈsikrəts ʌv səkˈsɛsfəl ˈɪŋɡlɪʃ ˈlɝnɪŋ/"},{"start":61.04,"end":64.8,"text":"You will know what to avoid and what to do instead.","words":[["You",61.04],["will",61.2],["know",61.36],["what",61.52],["to",61.76],["avoid",61.92],["and",62.56],["what",62.88],["to",63.04],["do",63.28],["instead.",63.52]],"ipa":"/ju wɪl noʊ wʌt tu əˈvɔɪd ənd wʌt tu du ˌɪnˈstɛd/"},{"start":64.8,"end":67.28,"text":"This is not just ideas.","words":[["This",64.8],["is",65.12],["not",65.36],["just",65.6],["ideas.",66]],"ipa":"/ðɪs ɪz nɑt dʒʌst aɪˈdiəz/"},{"start":67.28,"end":72.48,"text":"These are proven methods that can change your learning starting today.","words":[["These",67.28],["are",67.68],["proven",67.92],["methods",68.4],["that",68.88],["can",69.12],["change",69.36],["your",69.76],["learning",70],["starting",70.56],["today.",71.04]],"ipa":"/ðiz ɑr ˈpruvən ˈmɛθədz ðæt kæn tʃeɪndʒ jɔr ˈlɝnɪŋ ˈstɑrtɪŋ təˈdeɪ/"},{"start":72.48,"end":85.9,"text":"So, get your coffee or tea, sit back, and let us discover the truth about learning English that nobody talks about.","words":[["So,",72.48],["get",72.72],["your",72.96],["coffee",73.2],["or",73.6],["tea,",73.92],["sit",74.8],["back,",75.12],["and",75.92],["let",76.16],["us",76.4],["discover",76.56],["the",77.04],["truth",77.28],["about",77.68],["learning",78.08],["English",78.56],["that",79.04],["nobody",79.36],["talks",79.84],["about.",80.24]],"ipa":"/soʊ ɡɛt jɔr ˈkɑfi ɔr ti sɪt bæk ənd lɛt ʌs dɪˈskʌvər ðə truθ əˈbaʊt ˈlɝnɪŋ ˈɪŋɡlɪʃ ðæt ˈnoʊˌbɑˌdi tɔks əˈbaʊt/"},{"start":87.68,"end":94.56,"text":"Did you know that you need to see a new word five to 16 times before you remember it?","words":[["Did",87.68],["you",88],["know",88.16],["that",88.4],["you",88.64],["need",88.88],["to",89.04],["see",89.28],["a",89.52],["new",89.76],["word",90],["five",90.72],["to",91.04],["16",91.36],["times",91.92],["before",92.56],["you",92.96],["remember",93.28],["it?",93.6]],"ipa":"/dɪd ju noʊ ðæt ju nid tu si ə nu wɝd faɪv tu taɪmz bɪˈfɔr ju rɪˈmɛmbər ɪt/"},{"start":94.56,"end":102,"text":"But most English students expect to learn new words after seeing them just once or twice.","words":[["But",94.56],["most",94.8],["English",95.2],["students",95.68],["expect",96.4],["to",96.8],["learn",97.04],["new",97.36],["words",97.68],["after",98.4],["seeing",98.88],["them",99.2],["just",99.84],["once",100.16],["or",100.48],["twice.",100.72]],"ipa":"/bʌt moʊst ˈɪŋɡlɪʃ ˈstudənts ɪkˈspɛkt tu lɝn nu wɝdz ˈæftər ˈsiɪŋ ðɛm dʒʌst wʌns ɔr twaɪs/"},{"start":102,"end":108.4,"text":"This wrong thinking is just one of many problems that make learning English slower.","words":[["This",102],["wrong",102.32],["thinking",102.64],["is",103.28],["just",103.68],["one",104],["of",104.24],["many",104.4],["problems",104.8],["that",105.36],["make",105.68],["learning",106],["English",106.48],["slower.",106.88]],"ipa":"/ðɪs rɔŋ ˈθɪŋkɪŋ ɪz dʒʌst wʌn ʌv ˈmɛni ˈprɑbləmz ðæt meɪk ˈlɝnɪŋ ˈɪŋɡlɪʃ ˈsloʊər/"},{"start":108.4,"end":109.92,"text":"Think about babies.","words":[["Think",108.4],["about",108.64],["babies.",108.96]],"ipa":"/θɪŋk əˈbaʊt ˈbeɪbiz/"},{"start":109.92,"end":113.92,"text":"When they learn their first language, they make mistakes every day.","words":[["When",109.92],["they",110.16],["learn",110.4],["their",110.56],["first",110.88],["language,",111.12],["they",111.76],["make",112],["mistakes",112.24],["every",112.88],["day.",113.28]],"ipa":"/wɛn ðeɪ lɝn ðɛr fɝst ˈlæŋɡwədʒ ðeɪ meɪk mɪˈsteɪks ˈɛvəri deɪ/"},{"start":113.92,"end":117.44,"text":"They say, \\"I goed instead of I went.\\"","words":[["They",113.92],["say,",114.24],["\\"I",114.56],["goed",114.96],["instead",115.52],["of",115.92],["I",116.08],["went.\\"",116.32]],"ipa":"/ðeɪ seɪ aɪ goed ˌɪnˈstɛd ʌv aɪ wɛnt/"},{"start":117.44,"end":119.84,"text":"They put words in the wrong order.","words":[["They",117.44],["put",117.68],["words",118],["in",118.32],["the",118.56],["wrong",118.8],["order.",119.04]],"ipa":"/ðeɪ pʊt wɝdz ɪn ðə rɔŋ ˈɔrdər/"},{"start":119.84,"end":124.88,"text":"They make up new words that do not exist, but nobody stops them.","words":[["They",119.84],["make",120.08],["up",120.32],["new",120.56],["words",120.88],["that",121.2],["do",121.52],["not",121.68],["exist,",121.92],["but",122.72],["nobody",123.04],["stops",123.52],["them.",123.92]],"ipa":"/ðeɪ meɪk ʌp nu wɝdz ðæt du nɑt ɪɡˈzɪst bʌt ˈnoʊˌbɑˌdi stɑps ðɛm/"},{"start":124.88,"end":127.52,"text":"Nobody says they are bad at languages.","words":[["Nobody",124.88],["says",125.28],["they",125.6],["are",125.84],["bad",126.08],["at",126.32],["languages.",126.48]],"ipa":"/ˈnoʊˌbɑˌdi sɛz ðeɪ ɑr bæd æt ˈlæŋɡwədʒəz/"},{"start":127.52,"end":131.04,"text":"They just keep trying and playing with words.","words":[["They",127.52],["just",127.76],["keep",128],["trying",128.32],["and",128.8],["playing",129.04],["with",129.36],["words.",129.68]],"ipa":"/ðeɪ dʒʌst kip ˈtraɪɪŋ ənd ˈpleɪɪŋ wɪð wɝdz/"},{"start":131.04,"end":134.88,"text":"But when adults learn languages, something changes.","words":[["But",131.04],["when",131.2],["adults",131.44],["learn",131.92],["languages,",132.32],["something",133.28],["changes.",133.76]],"ipa":"/bʌt wɛn əˈdʌlts lɝn ˈlæŋɡwədʒəz ˈsʌmθɪŋ ˈtʃeɪndʒəz/"},{"start":134.88,"end":137.04,"text":"We become afraid of mistakes.","words":[["We",134.88],["become",135.12],["afraid",135.36],["of",135.76],["mistakes.",136]],"ipa":"/wi bɪˈkʌm əˈfreɪd ʌv mɪˈsteɪks/"},{"start":137.04,"end":140.48,"text":"We want everything to be perfect right away.","words":[["We",137.04],["want",137.36],["everything",137.52],["to",137.92],["be",138.16],["perfect",138.4],["right",138.96],["away.",139.28]],"ipa":"/wi wɑnt ˈɛvriˌθɪŋ tu bi pərˈfɛkt raɪt əˈweɪ/"},{"start":140.48,"end":146.32,"text":"This new way of thinking creates big problems that can stop us for years.","words":[["This",140.48],["new",140.72],["way",140.96],["of",141.2],["thinking",141.36],["creates",142],["big",142.56],["problems",142.96],["that",143.44],["can",143.76],["stop",144],["us",144.24],["for",144.48],["years.",144.72]],"ipa":"/ðɪs nu weɪ ʌv ˈθɪŋkɪŋ kriˈeɪts bɪɡ ˈprɑbləmz ðæt kæn stɑp ʌs fɔr jɪrz/"},{"start":146.32,"end":149.52,"text":"Scientists have studied this many times.","words":[["Scientists",146.32],["have",147.04],["studied",147.36],["this",147.84],["many",148.08],["times.",148.4]],"ipa":"/ˈsaɪəntɪsts hæv ˈstʌdid ðɪs ˈmɛni taɪmz/"},{"start":149.52,"end":161.2,"text":"They found that adult language learners often create their own biggest problems not because they are not smart or do not work hard but because they fall into","words":[["They",149.52],["found",149.84],["that",150],["adult",150.32],["language",150.8],["learners",151.28],["often",152],["create",152.56],["their",153.04],["own",153.36],["biggest",153.68],["problems",154.16],["not",155.52],["because",155.84],["they",156.16],["are",156.4],["not",156.56],["smart",156.88],["or",157.52],["do",157.84],["not",158.16],["work",158.4],["hard",158.64],["but",159.52],["because",159.76],["they",160.08],["fall",160.48],["into",160.72]],"ipa":"/ðeɪ faʊnd ðæt əˈdʌlt ˈlæŋɡwədʒ ˈlɝnərz ˈɔfən kriˈeɪt ðɛr oʊn ˈbɪɡəst ˈprɑbləmz nɑt bɪˈkɔz ðeɪ ɑr nɑt smɑrt ɔr du nɑt wɝk hɑrd bʌt bɪˈkɔz ðeɪ fɔl ˈɪntu/"},{"start":161.2,"end":164.64,"text":"common traps that hurt their progress.","words":[["common",161.2],["traps",161.68],["that",162.24],["hurt",162.56],["their",162.88],["progress.",163.12]],"ipa":"/ˈkɑmən træps ðæt hɝt ðɛr ˈprɑˌɡrɛs/"},{"start":164.64,"end":167.2,"text":"The fear of speaking trap.","words":[["The",164.64],["fear",164.96],["of",165.2],["speaking",165.44],["trap.",165.92]],"ipa":"/ðə fɪr ʌv ˈspikɪŋ træp/"},{"start":167.2,"end":171.44,"text":"The first and biggest trap is being too afraid to speak.","words":[["The",167.2],["first",167.52],["and",167.76],["biggest",168.08],["trap",168.48],["is",168.88],["being",169.12],["too",169.44],["afraid",169.76],["to",170.08],["speak.",170.4]],"ipa":"/ðə fɝst ənd ˈbɪɡəst træp ɪz ˈbiɪŋ tu əˈfreɪd tu spik/"},{"start":171.44,"end":179.28,"text":"This happens when students become so scared of making mistakes that they stop talking in English completely.","words":[["This",171.44],["happens",171.76],["when",172.24],["students",172.64],["become",173.12],["so",173.68],["scared",174.08],["of",174.48],["making",174.8],["mistakes",175.2],["that",175.68],["they",176],["stop",176.32],["talking",176.72],["in",177.2],["English",177.44],["completely.",177.92]],"ipa":"/ðɪs ˈhæpənz wɛn ˈstudənts bɪˈkʌm soʊ skɛrd ʌv ˈmeɪkɪŋ mɪˈsteɪks ðæt ðeɪ stɑp ˈtɔkɪŋ ɪn ˈɪŋɡlɪʃ kəmˈplitli/"},{"start":179.28,"end":186.8,"text":"They spend months studying grammar books, learning vocabulary lists, and watching English videos.","words":[["They",179.28],["spend",179.6],["months",179.92],["studying",180.48],["grammar",181.04],["books,",181.52],["learning",182.4],["vocabulary",182.88],["lists,",183.68],["and",184.24],["watching",184.56],["English",185.12],["videos.",185.6]],"ipa":"/ðeɪ spɛnd mʌnθs ˈstʌdiɪŋ ˈɡræmər bʊks ˈlɝnɪŋ voʊˈkæbjəˌlɛri lɪsts ənd ˈwɑtʃɪŋ ˈɪŋɡlɪʃ ˈvɪdioʊz/"},{"start":186.8,"end":190.64,"text":"But when they need to actually speak, they cannot do it.","words":[["But",186.8],["when",186.96],["they",187.12],["need",187.36],["to",187.52],["actually",187.84],["speak,",188.32],["they",189.12],["cannot",189.44],["do",189.84],["it.",190]],"ipa":"/bʌt wɛn ðeɪ nid tu ˈækˌtʃuəli spik ðeɪ ˈkænɑt du ɪt/"},{"start":190.64,"end":195.04,"text":"Here is what happens in a scared students mind.","words":[["Here",190.64],["is",191.52],["what",191.76],["happens",192],["in",192.4],["a",192.64],["scared",192.88],["students",193.36],["mind.",193.92]],"ipa":"/hir ɪz wʌt ˈhæpənz ɪn ə skɛrd ˈstudənts maɪnd/"},{"start":195.04,"end":198.48,"text":"Before speaking, they think about every word.","words":[["Before",195.04],["speaking,",195.52],["they",196.24],["think",196.56],["about",196.72],["every",197.12],["word.",197.52]],"ipa":"/bɪˈfɔr ˈspikɪŋ ðeɪ θɪŋk əˈbaʊt ˈɛvəri wɝd/"},{"start":198.48,"end":200.96,"text":"They check if the grammar is right.","words":[["They",198.48],["check",198.8],["if",199.04],["the",199.28],["grammar",199.52],["is",199.92],["right.",200.24]],"ipa":"/ðeɪ tʃɛk ɪf ðə ˈɡræmər ɪz raɪt/"},{"start":200.96,"end":203.36,"text":"They worry about their accent.","words":[["They",200.96],["worry",201.28],["about",201.6],["their",201.92],["accent.",202.24]],"ipa":"/ðeɪ ˈwɝi əˈbaʊt ðɛr əkˈsɛnt/"},{"start":203.36,"end":207.04,"text":"They imagine all the bad things that might happen.","words":[["They",203.36],["imagine",203.68],["all",204.24],["the",204.56],["bad",204.8],["things",205.2],["that",205.52],["might",205.84],["happen.",206.08]],"ipa":"/ðeɪ ˌɪˈmædʒən ɔl ðə bæd θɪŋz ðæt maɪt ˈhæpən/"},{"start":207.04,"end":211.44,"text":"By the time they finish thinking, the conversation is over.","words":[["By",207.04],["the",207.28],["time",207.44],["they",207.68],["finish",207.92],["thinking,",208.32],["the",209.04],["conversation",209.28],["is",210],["over.",210.32]],"ipa":"/baɪ ðə taɪm ðeɪ ˈfɪnɪʃ ˈθɪŋkɪŋ ðə ˌkɑnvərˈseɪʃən ɪz ˈoʊvər/"},{"start":211.44,"end":214.48,"text":"The chance to speak is gone.","words":[["The",211.44],["chance",211.68],["to",212],["speak",212.32],["is",212.64],["gone.",212.96]],"ipa":"/ðə tʃæns tu spik ɪz ɡɔn/"},{"start":214.48,"end":219.44,"text":"This trap is very dangerous because it feels like you are working hard.","words":[["This",214.48],["trap",214.8],["is",215.2],["very",215.44],["dangerous",215.84],["because",216.48],["it",216.8],["feels",217.04],["like",217.36],["you",217.6],["are",217.84],["working",218.08],["hard.",218.4]],"ipa":"/ðɪs træp ɪz ˈvɛri ˈdeɪndʒərəs bɪˈkɔz ɪt filz laɪk ju ɑr ˈwɝkɪŋ hɑrd/"},{"start":219.44,"end":220.96,"text":"You are studying.","words":[["You",219.44],["are",219.68],["studying.",219.92]],"ipa":"/ju ɑr ˈstʌdiɪŋ/"},{"start":220.96,"end":223.04,"text":"You are learning new words.","words":[["You",220.96],["are",221.2],["learning",221.36],["new",221.76],["words.",222.08]],"ipa":"/ju ɑr ˈlɝnɪŋ nu wɝdz/"},{"start":223.04,"end":226,"text":"You understand more and more English.","words":[["You",223.04],["understand",223.28],["more",224],["and",224.32],["more",224.56],["English.",224.88]],"ipa":"/ju ˌʌndərˈstænd mɔr ənd mɔr ˈɪŋɡlɪʃ/"},{"start":226,"end":231.2,"text":"But without speaking practice, your skills stay locked in your head.","words":[["But",226],["without",226.16],["speaking",226.64],["practice,",227.12],["your",228.16],["skills",228.48],["stay",229.04],["locked",229.44],["in",229.84],["your",230],["head.",230.24]],"ipa":"/bʌt wɪˈθaʊt ˈspikɪŋ ˈpræktəs jɔr skɪlz steɪ lɑkt ɪn jɔr hɛd/"},{"start":231.2,"end":236.32,"text":"You can understand everything but cannot use English when you need it most.","words":[["You",231.2],["can",231.44],["understand",231.6],["everything",232.24],["but",232.88],["cannot",233.2],["use",233.52],["English",233.92],["when",234.24],["you",234.56],["need",234.64],["it",234.8],["most.",235.04]],"ipa":"/ju kæn ˌʌndərˈstænd ˈɛvriˌθɪŋ bʌt ˈkænɑt jus ˈɪŋɡlɪʃ wɛn ju nid ɪt moʊst/"},{"start":236.32,"end":240.32,"text":"The answer starts with changing how you think about mistakes.","words":[["The",236.32],["answer",236.56],["starts",236.96],["with",237.36],["changing",237.6],["how",238.16],["you",238.4],["think",238.64],["about",238.8],["mistakes.",239.12]],"ipa":"/ðə ˈænsər stɑrts wɪð ˈtʃeɪndʒɪŋ haʊ ju θɪŋk əˈbaʊt mɪˈsteɪks/"},{"start":240.32,"end":246.72,"text":"Instead of seeing errors as bad things, good learners see them as helpful information.","words":[["Instead",240.32],["of",240.72],["seeing",240.88],["errors",241.44],["as",241.76],["bad",242.08],["things,",242.48],["good",243.2],["learners",243.52],["see",244],["them",244.24],["as",244.48],["helpful",244.8],["information.",245.36]],"ipa":"/ˌɪnˈstɛd ʌv ˈsiɪŋ ˈɛrərz æz bæd θɪŋz ɡʊd ˈlɝnərz si ðɛm æz ˈhɛlpfəl ˌɪnfərˈmeɪʃən/"},{"start":246.72,"end":251.84,"text":"Each mistake tells you something important about what you need to practice.","words":[["Each",246.72],["mistake",247.12],["tells",247.76],["you",248],["something",248.24],["important",248.72],["about",249.36],["what",249.68],["you",249.92],["need",250.08],["to",250.24],["practice.",250.48]],"ipa":"/itʃ mɪˈsteɪk tɛlz ju ˈsʌmθɪŋ ˌɪmˈpɔrtənt əˈbaʊt wʌt ju nid tu ˈpræktəs/"},{"start":251.84,"end":254.72,"text":"Native speakers make mistakes, too.","words":[["Native",251.84],["speakers",252.4],["make",252.96],["mistakes,",253.2],["too.",253.92]],"ipa":"/ˈneɪtɪv ˈspikərz meɪk mɪˈsteɪks tu/"},{"start":254.72,"end":260.8,"text":"They forget words, say wrong things, and use bad grammar sometimes.","words":[["They",254.72],["forget",255.04],["words,",255.44],["say",256.4],["wrong",256.72],["things,",257.12],["and",257.84],["use",258.08],["bad",258.4],["grammar",258.8],["sometimes.",259.36]],"ipa":"/ðeɪ fərˈɡɛt wɝdz seɪ rɔŋ θɪŋz ənd jus bæd ˈɡræmər səmˈtaɪmz/"},{"start":260.8,"end":266.08,"text":"The difference is they do not let small problems stop them from talking.","words":[["The",260.8],["difference",261.12],["is",261.44],["they",261.76],["do",262.08],["not",262.24],["let",262.48],["small",262.72],["problems",263.12],["stop",263.76],["them",264.08],["from",264.32],["talking.",264.56]],"ipa":"/ðə ˈdɪfərəns ɪz ðeɪ du nɑt lɛt smɔl ˈprɑbləmz stɑp ðɛm frʌm ˈtɔkɪŋ/"},{"start":266.08,"end":267.76,"text":"Try this method.","words":[["Try",266.08],["this",266.48],["method.",266.8]],"ipa":"/traɪ ðɪs ˈmɛθəd/"},{"start":267.76,"end":274.24,"text":"Set a daily speaking goal that focuses on communication, not being perfect.","words":[["Set",267.76],["a",267.92],["daily",268.16],["speaking",268.72],["goal",269.2],["that",269.52],["focuses",269.92],["on",270.48],["communication,",270.88],["not",272.24],["being",272.56],["perfect.",272.88]],"ipa":"/sɛt ə ˈdeɪli ˈspikɪŋ ɡoʊl ðæt ˈfoʊkəsɪz ɑn kəmˌjunəˈkeɪʃən nɑt ˈbiɪŋ pərˈfɛkt/"},{"start":274.24,"end":278.48,"text":"Maybe record yourself talking about your day for 2 minutes.","words":[["Maybe",274.24],["record",274.64],["yourself",275.04],["talking",275.52],["about",275.92],["your",276.16],["day",276.4],["for",276.72],["2",276.96],["minutes.",277.28]],"ipa":"/ˈmeɪbi rəˈkɔrd jərˈsɛlf ˈtɔkɪŋ əˈbaʊt jɔr deɪ fɔr ˈmɪnəts/"},{"start":278.48,"end":282.48,"text":"Maybe write comments on social media in English.","words":[["Maybe",278.48],["write",278.88],["comments",279.28],["on",279.76],["social",280.16],["media",280.56],["in",281.04],["English.",281.36]],"ipa":"/ˈmeɪbi raɪt ˈkɑmɛnts ɑn ˈsoʊʃəl ˈmidiə ɪn ˈɪŋɡlɪʃ/"},{"start":282.48,"end":285.6,"text":"Maybe talk to yourself while making dinner.","words":[["Maybe",282.48],["talk",282.8],["to",283.04],["yourself",283.28],["while",283.76],["making",284.08],["dinner.",284.48]],"ipa":"/ˈmeɪbi tɔk tu jərˈsɛlf waɪl ˈmeɪkɪŋ ˈdɪnər/"},{"start":285.6,"end":293.28,"text":"The important thing is to make mistakes in a safe place where you can learn from them without feeling bad.","words":[["The",285.6],["important",285.92],["thing",286.4],["is",286.64],["to",286.88],["make",287.2],["mistakes",287.44],["in",288],["a",288.24],["safe",288.48],["place",288.8],["where",289.36],["you",289.68],["can",289.84],["learn",290],["from",290.24],["them",290.56],["without",290.88],["feeling",291.36],["bad.",291.84]],"ipa":"/ðə ˌɪmˈpɔrtənt θɪŋ ɪz tu meɪk mɪˈsteɪks ɪn ə seɪf pleɪs wɛr ju kæn lɝn frʌm ðɛm wɪˈθaʊt ˈfilɪŋ bæd/"},{"start":293.28,"end":295.44,"text":"Start with simple topics.","words":[["Start",293.28],["with",293.6],["simple",293.84],["topics.",294.32]],"ipa":"/stɑrt wɪð ˈsɪmpəl ˈtɑpɪks/"},{"start":295.44,"end":297.84,"text":"Talk about your morning routine.","words":[["Talk",295.44],["about",295.76],["your",296],["morning",296.24],["routine.",296.64]],"ipa":"/tɔk əˈbaʊt jɔr ˈmɔrnɪŋ ruˈtin/"},{"start":297.84,"end":300.64,"text":"Describe what you see outside your window.","words":[["Describe",297.84],["what",298.32],["you",298.56],["see",298.72],["outside",298.96],["your",299.44],["window.",299.76]],"ipa":"/dɪˈskraɪb wʌt ju si ˈaʊtˈsaɪd jɔr ˈwɪndoʊ/"},{"start":300.64,"end":303.68,"text":"Tell a story about your last weekend.","words":[["Tell",300.64],["a",300.88],["story",301.12],["about",301.52],["your",301.84],["last",302.08],["weekend.",302.48]],"ipa":"/tɛl ə ˈstɔri əˈbaʊt jɔr læst ˈwiˌkɛnd/"},{"start":303.68,"end":308.16,"text":"Do not worry about perfect grammar or pronunciation.","words":[["Do",303.68],["not",304],["worry",304.24],["about",304.56],["perfect",304.96],["grammar",305.6],["or",306.16],["pronunciation.",306.48]],"ipa":"/du nɑt ˈwɝi əˈbaʊt pərˈfɛkt ˈɡræmər ɔr proʊˌnʌnsiˈeɪʃən/"},{"start":308.16,"end":311.2,"text":"Focus on getting your message across.","words":[["Focus",308.16],["on",308.64],["getting",308.96],["your",309.36],["message",309.6],["across.",310]],"ipa":"/ˈfoʊkəs ɑn ˈɡɛtɪŋ jɔr ˈmɛsədʒ əˈkrɔs/"},{"start":311.2,"end":315.52,"text":"The more you practice, the more natural it becomes.","words":[["The",311.2],["more",311.44],["you",311.68],["practice,",311.92],["the",312.8],["more",313.04],["natural",313.28],["it",313.68],["becomes.",314]],"ipa":"/ðə mɔr ju ˈpræktəs ðə mɔr ˈnætʃərəl ɪt bɪˈkʌmz/"},{"start":315.52,"end":318.88,"text":"Remember that speaking is like any other skill.","words":[["Remember",315.52],["that",315.84],["speaking",316.32],["is",316.8],["like",317.04],["any",317.36],["other",317.68],["skill.",317.92]],"ipa":"/rɪˈmɛmbər ðæt ˈspikɪŋ ɪz laɪk ˈɛni ˈʌðər skɪl/"},{"start":318.88,"end":324.88,"text":"You would not expect to play piano perfectly after reading music books for months.","words":[["You",318.88],["would",319.12],["not",319.36],["expect",319.6],["to",319.92],["play",320.24],["piano",320.56],["perfectly",321.2],["after",322],["reading",322.4],["music",322.88],["books",323.28],["for",323.6],["months.",323.92]],"ipa":"/ju wʊd nɑt ɪkˈspɛkt tu pleɪ piˈænoʊ ˈpɝfəktli ˈæftər ˈridɪŋ ˈmjuzɪk bʊks fɔr mʌnθs/"},{"start":324.88,"end":327.76,"text":"You need to practice pressing the keys.","words":[["You",324.88],["need",325.12],["to",325.28],["practice",325.44],["pressing",326.08],["the",326.48],["keys.",326.72]],"ipa":"/ju nid tu ˈpræktəs ˈprɛsɪŋ ðə kiz/"},{"start":327.76,"end":330.4,"text":"The same is true for English.","words":[["The",327.76],["same",328.08],["is",328.4],["true",328.8],["for",329.12],["English.",329.44]],"ipa":"/ðə seɪm ɪz tru fɔr ˈɪŋɡlɪʃ/"},{"start":330.4,"end":335.12,"text":"You need to practice moving your mouth and making sounds.","words":[["You",330.4],["need",330.72],["to",330.8],["practice",331.04],["moving",331.68],["your",332],["mouth",332.32],["and",332.72],["making",333.04],["sounds.",333.52]],"ipa":"/ju nid tu ˈpræktəs ˈmuvɪŋ jɔr maʊθ ənd ˈmeɪkɪŋ saʊndz/"},{"start":335.12,"end":338.16,"text":"Create speaking opportunities every day.","words":[["Create",335.12],["speaking",335.6],["opportunities",336.08],["every",336.96],["day.",337.36]],"ipa":"/kriˈeɪt ˈspikɪŋ ˌɑpərˈtunətiz ˈɛvəri deɪ/"},{"start":338.16,"end":340.64,"text":"Talk to yourself in the mirror.","words":[["Talk",338.16],["to",338.4],["yourself",338.64],["in",339.12],["the",339.36],["mirror.",339.52]],"ipa":"/tɔk tu jərˈsɛlf ɪn ðə ˈmɪrər/"},{"start":340.64,"end":342.64,"text":"Read books out loud.","words":[["Read",340.64],["books",341.04],["out",341.44],["loud.",341.68]],"ipa":"/rɛd bʊks aʊt laʊd/"},{"start":342.64,"end":346.16,"text":"Repeat after movies and TV shows.","words":[["Repeat",342.64],["after",343.12],["movies",343.6],["and",344.08],["TV",344.48],["shows.",344.88]],"ipa":"/rɪˈpit ˈæftər ˈmuviz ənd ˈtiˈvi ʃoʊz/"},{"start":346.16,"end":349.04,"text":"Join online conversation groups.","words":[["Join",346.16],["online",346.56],["conversation",347.2],["groups.",348.08]],"ipa":"/dʒɔɪn ˈɔnˌlaɪn ˌkɑnvərˈseɪʃən ɡrups/"},{"start":349.04,"end":355.28,"text":"The key is to speak regularly, even if it is just for a few minutes each day.","words":[["The",349.04],["key",349.36],["is",349.52],["to",349.76],["speak",350],["regularly,",350.4],["even",351.6],["if",351.84],["it",352.08],["is",352.24],["just",352.48],["for",352.8],["a",352.96],["few",353.2],["minutes",353.36],["each",353.68],["day.",354.08]],"ipa":"/ðə ki ɪz tu spik ˈrɛɡjələrli ˈivɪn ɪf ɪt ɪz dʒʌst fɔr ə fju ˈmɪnəts itʃ deɪ/"},{"start":355.28,"end":357.6,"text":"The grammar study trap.","words":[["The",355.28],["grammar",355.52],["study",356],["trap.",356.4]],"ipa":"/ðə ˈɡræmər ˈstʌdi træp/"},{"start":357.6,"end":361.36,"text":"The second big trap is studying grammar too much.","words":[["The",357.6],["second",357.84],["big",358.16],["trap",358.48],["is",358.8],["studying",359.12],["grammar",359.6],["too",360.08],["much.",360.32]],"ipa":"/ðə ˈsɛkənd bɪɡ træp ɪz ˈstʌdiɪŋ ˈɡræmər tu mʌtʃ/"},{"start":361.36,"end":367.76,"text":"Many students believe that learning all English grammar rules is the key to speaking well.","words":[["Many",361.36],["students",361.76],["believe",362.32],["that",362.64],["learning",362.96],["all",363.52],["English",363.84],["grammar",364.32],["rules",364.8],["is",365.36],["the",365.6],["key",365.84],["to",366.08],["speaking",366.32],["well.",366.8]],"ipa":"/ˈmɛni ˈstudənts bɪˈliv ðæt ˈlɝnɪŋ ɔl ˈɪŋɡlɪʃ ˈɡræmər rulz ɪz ðə ki tu ˈspikɪŋ wɛl/"},{"start":367.76,"end":376.16,"text":"They spend years studying complex rules, memorizing exceptions, and analyzing sentence patterns.","words":[["They",367.76],["spend",368.08],["years",368.4],["studying",368.88],["complex",369.52],["rules,",370.16],["memorizing",371.12],["exceptions,",372],["and",373.12],["analyzing",373.44],["sentence",374.32],["patterns.",374.88]],"ipa":"/ðeɪ spɛnd jɪrz ˈstʌdiɪŋ ˈkɑmplɛks rulz ˈmɛmərˌaɪzɪŋ ɪkˈsɛpʃənz ənd ˈænəˌlaɪzɪŋ ˈsɛntəns ˈpætərnz/"},{"start":376.16,"end":383.12,"text":"While grammar is important, this method often creates more problems than it solves.","words":[["While",376.16],["grammar",376.48],["is",377.04],["important,",377.36],["this",378.4],["method",378.72],["often",379.2],["creates",379.76],["more",380.32],["problems",380.72],["than",381.28],["it",381.44],["solves.",381.68]],"ipa":"/waɪl ˈɡræmər ɪz ˌɪmˈpɔrtənt ðɪs ˈmɛθəd ˈɔfən kriˈeɪts mɔr ˈprɑbləmz ðæn ɪt sɑlvz/"},{"start":383.12,"end":389.68,"text":"When you focus too much on grammar, you start thinking like a computer instead of a person.","words":[["When",383.12],["you",383.36],["focus",383.6],["too",384],["much",384.32],["on",384.48],["grammar,",384.72],["you",385.6],["start",385.84],["thinking",386.16],["like",386.56],["a",386.8],["computer",387.12],["instead",387.76],["of",388.08],["a",388.24],["person.",388.48]],"ipa":"/wɛn ju ˈfoʊkəs tu mʌtʃ ɑn ˈɡræmər ju stɑrt ˈθɪŋkɪŋ laɪk ə kəmpˈjutər ˌɪnˈstɛd ʌv ə ˈpɝsən/"},{"start":389.68,"end":394.4,"text":"You pause in the middle of sentences to think about verb tenses.","words":[["You",389.68],["pause",389.92],["in",390.24],["the",390.48],["middle",390.64],["of",390.8],["sentences",391.04],["to",391.76],["think",392.08],["about",392.32],["verb",392.72],["tenses.",393.12]],"ipa":"/ju pɔz ɪn ðə ˈmɪdəl ʌv ˈsɛntənsəz tu θɪŋk əˈbaʊt vɝb tenses/"},{"start":394.4,"end":400,"text":"You worry about whether to use the or a in different situations.","words":[["You",394.4],["worry",394.64],["about",394.96],["whether",395.2],["to",395.52],["use",395.84],["the",396.4],["or",396.88],["a",397.36],["in",397.84],["different",398.08],["situations.",398.4]],"ipa":"/ju ˈwɝi əˈbaʊt ˈwɛðər tu jus ðə ɔr ə ɪn ˈdɪfərənt ˌsɪtʃuˈeɪʃənz/"},{"start":400,"end":404.16,"text":"You lose the natural flow of conversation.","words":[["You",400],["lose",400.24],["the",400.56],["natural",400.88],["flow",401.44],["of",401.84],["conversation.",402.16]],"ipa":"/ju luz ðə ˈnætʃərəl floʊ ʌv ˌkɑnvərˈseɪʃən/"},{"start":404.16,"end":410.08,"text":"Research shows that children learn their first language without studying grammar rules.","words":[["Research",404.16],["shows",404.72],["that",405.04],["children",405.44],["learn",406],["their",406.24],["first",406.56],["language",406.8],["without",407.44],["studying",407.92],["grammar",408.48],["rules.",408.96]],"ipa":"/riˈsɝtʃ ʃoʊz ðæt ˈtʃɪldrən lɝn ðɛr fɝst ˈlæŋɡwədʒ wɪˈθaʊt ˈstʌdiɪŋ ˈɡræmər rulz/"},{"start":410.08,"end":414.24,"text":"They learn patterns by listening and practicing.","words":[["They",410.08],["learn",410.4],["patterns",410.72],["by",411.44],["listening",411.76],["and",412.4],["practicing.",412.8]],"ipa":"/ðeɪ lɝn ˈpætərnz baɪ ˈlɪsənɪŋ ənd ˈpræktəsɪŋ/"},{"start":414.24,"end":419.92,"text":"They develop a natural feeling for what sounds right and what sounds wrong.","words":[["They",414.24],["develop",414.56],["a",414.96],["natural",415.28],["feeling",415.76],["for",416.16],["what",416.48],["sounds",416.72],["right",417.12],["and",417.68],["what",418],["sounds",418.32],["wrong.",418.72]],"ipa":"/ðeɪ dɪˈvɛləp ə ˈnætʃərəl ˈfilɪŋ fɔr wʌt saʊndz raɪt ənd wʌt saʊndz rɔŋ/"},{"start":419.92,"end":428.64,"text":"This same natural process can work for adult learners, but only if you do not think too much about every sentence.","words":[["This",419.92],["same",420.16],["natural",420.64],["process",421.2],["can",421.84],["work",422.16],["for",422.4],["adult",422.64],["learners,",423.12],["but",424.08],["only",424.4],["if",424.64],["you",424.88],["do",425.04],["not",425.2],["think",425.44],["too",425.68],["much",426],["about",426.24],["every",426.64],["sentence.",427.12]],"ipa":"/ðɪs seɪm ˈnætʃərəl ˈprɑˌsɛs kæn wɝk fɔr əˈdʌlt ˈlɝnərz bʌt ˈoʊnli ɪf ju du nɑt θɪŋk tu mʌtʃ əˈbaʊt ˈɛvəri ˈsɛntəns/"},{"start":428.64,"end":432.56,"text":"The best English speakers are not grammar experts.","words":[["The",428.64],["best",428.88],["English",429.2],["speakers",429.68],["are",430.32],["not",430.56],["grammar",430.88],["experts.",431.44]],"ipa":"/ðə bɛst ˈɪŋɡlɪʃ ˈspikərz ɑr nɑt ˈɡræmər ˈɛkspərts/"},{"start":432.56,"end":435.04,"text":"They are communication experts.","words":[["They",432.56],["are",432.8],["communication",433.04],["experts.",433.92]],"ipa":"/ðeɪ ɑr kəmˌjunəˈkeɪʃən ˈɛkspərts/"},{"start":435.04,"end":439.52,"text":"They know how to share their ideas clearly and effectively.","words":[["They",435.04],["know",435.28],["how",435.44],["to",435.6],["share",435.84],["their",436.08],["ideas",436.4],["clearly",437.12],["and",437.68],["effectively.",438.08]],"ipa":"/ðeɪ noʊ haʊ tu ʃɛr ðɛr aɪˈdiəz ˈklɪrli ənd ɪˈfɛktɪvli/"},{"start":439.52,"end":447.36,"text":"They understand that talking is about connecting with people, not about showing perfect grammar knowledge.","words":[["They",439.52],["understand",439.84],["that",440.32],["talking",440.72],["is",441.2],["about",441.52],["connecting",441.84],["with",442.4],["people,",442.72],["not",443.6],["about",443.84],["showing",444.16],["perfect",444.8],["grammar",445.36],["knowledge.",445.84]],"ipa":"/ðeɪ ˌʌndərˈstænd ðæt ˈtɔkɪŋ ɪz əˈbaʊt kəˈnɛktɪŋ wɪð ˈpipəl nɑt əˈbaʊt ˈʃoʊɪŋ pərˈfɛkt ˈɡræmər ˈnɑlədʒ/"},{"start":447.36,"end":450.32,"text":"Here is a better way to learn grammar.","words":[["Here",447.36],["is",447.68],["a",447.92],["better",448.16],["way",448.4],["to",448.64],["learn",448.88],["grammar.",449.2]],"ipa":"/hir ɪz ə ˈbɛtər weɪ tu lɝn ˈɡræmər/"},{"start":450.32,"end":456.08,"text":"Instead of studying rules by themselves, learn them in real situations.","words":[["Instead",450.32],["of",450.72],["studying",450.88],["rules",451.36],["by",451.84],["themselves,",452.08],["learn",453.2],["them",453.52],["in",453.84],["real",454.16],["situations.",454.56]],"ipa":"/ˌɪnˈstɛd ʌv ˈstʌdiɪŋ rulz baɪ ðɛmˈsɛlvz lɝn ðɛm ɪn ril ˌsɪtʃuˈeɪʃənz/"},{"start":456.08,"end":463.36,"text":"When you hear a new structure in a conversation or movie, notice how people use it naturally.","words":[["When",456.08],["you",456.32],["hear",456.48],["a",456.72],["new",456.96],["structure",457.28],["in",457.76],["a",458],["conversation",458.24],["or",459.04],["movie,",459.44],["notice",460.32],["how",460.72],["people",461.04],["use",461.44],["it",461.68],["naturally.",461.92]],"ipa":"/wɛn ju hir ə nu ˈstrʌktʃər ɪn ə ˌkɑnvərˈseɪʃən ɔr ˈmuvi ˈnoʊtəs haʊ ˈpipəl jus ɪt ˈnætʃərəli/"},{"start":463.36,"end":467.12,"text":"Pay attention to the rhythm and music of the language.","words":[["Pay",463.36],["attention",463.68],["to",464.16],["the",464.4],["rhythm",464.64],["and",464.96],["music",465.28],["of",465.6],["the",465.76],["language.",466]],"ipa":"/peɪ əˈtɛnʃən tu ðə ˈrɪðəm ənd ˈmjuzɪk ʌv ðə ˈlæŋɡwədʒ/"},{"start":467.12,"end":470.32,"text":"Let your ear learn what sounds right.","words":[["Let",467.12],["your",467.36],["ear",467.6],["learn",467.92],["what",468.32],["sounds",468.64],["right.",469.04]],"ipa":"/lɛt jɔr ir lɝn wʌt saʊndz raɪt/"},{"start":470.32,"end":475.52,"text":"Focus on the grammar that you actually need for daily communication.","words":[["Focus",470.32],["on",470.72],["the",470.96],["grammar",471.12],["that",471.68],["you",472],["actually",472.32],["need",472.72],["for",473.04],["daily",473.36],["communication.",473.84]],"ipa":"/ˈfoʊkəs ɑn ðə ˈɡræmər ðæt ju ˈækˌtʃuəli nid fɔr ˈdeɪli kəmˌjunəˈkeɪʃən/"},{"start":475.52,"end":479.2,"text":"Most conversations use simple structures.","words":[["Most",475.52],["conversations",476],["use",477.04],["simple",477.36],["structures.",477.84]],"ipa":"/moʊst ˌkɑnvərˈseɪʃənz jus ˈsɪmpəl ˈstrʌktʃərz/"},{"start":479.2,"end":482.32,"text":"Learn these basic patterns first.","words":[["Learn",479.2],["these",479.52],["basic",479.92],["patterns",480.48],["first.",481.12]],"ipa":"/lɝn ðiz ˈbeɪsɪk ˈpætərnz fɝst/"},{"start":482.32,"end":488.32,"text":"Advanced grammar rules can wait until you are comfortable with everyday talking.","words":[["Advanced",482.32],["grammar",482.88],["rules",483.36],["can",483.84],["wait",484.08],["until",484.56],["you",484.88],["are",485.12],["comfortable",485.28],["with",485.84],["everyday",486.16],["talking.",486.8]],"ipa":"/ədˈvænst ˈɡræmər rulz kæn weɪt ənˈtɪl ju ɑr ˈkʌmfərtəbəl wɪð ˈɛvriˈdeɪ ˈtɔkɪŋ/"},{"start":488.32,"end":494,"text":"Practice grammar through speaking and writing, not just reading about rules.","words":[["Practice",488.32],["grammar",488.96],["through",489.52],["speaking",489.84],["and",490.32],["writing,",490.72],["not",491.6],["just",491.76],["reading",492.08],["about",492.48],["rules.",492.88]],"ipa":"/ˈpræktəs ˈɡræmər θru ˈspikɪŋ ənd ˈraɪtɪŋ nɑt dʒʌst ˈridɪŋ əˈbaʊt rulz/"},{"start":494,"end":497.76,"text":"When you learn a new tense, make sentences with it.","words":[["When",494],["you",494.24],["learn",494.4],["a",494.56],["new",494.8],["tense,",495.04],["make",495.76],["sentences",496.08],["with",496.64],["it.",496.96]],"ipa":"/wɛn ju lɝn ə nu tɛns meɪk ˈsɛntənsəz wɪð ɪt/"},{"start":497.76,"end":500.24,"text":"Use it in conversations.","words":[["Use",497.76],["it",498.08],["in",498.32],["conversations.",498.64]],"ipa":"/jus ɪt ɪn ˌkɑnvərˈseɪʃənz/"},{"start":500.24,"end":502.64,"text":"Write short stories with it.","words":[["Write",500.24],["short",500.64],["stories",501.04],["with",501.52],["it.",501.76]],"ipa":"/raɪt ʃɔrt ˈstɔriz wɪð ɪt/"},{"start":502.64,"end":508.56,"text":"This active practice helps you remember better than just reading explanations.","words":[["This",502.64],["active",502.96],["practice",503.52],["helps",504.16],["you",504.48],["remember",504.72],["better",505.12],["than",505.52],["just",505.76],["reading",506.08],["explanations.",506.56]],"ipa":"/ðɪs ˈæktɪv ˈpræktəs hɛlps ju rɪˈmɛmbər ˈbɛtər ðæn dʒʌst ˈridɪŋ ˌɛkspləˈneɪʃənz/"},{"start":508.56,"end":513.04,"text":"Do not worry about making grammar mistakes while speaking.","words":[["Do",508.56],["not",508.88],["worry",509.12],["about",509.44],["making",509.84],["grammar",510.24],["mistakes",510.72],["while",511.36],["speaking.",511.76]],"ipa":"/du nɑt ˈwɝi əˈbaʊt ˈmeɪkɪŋ ˈɡræmər mɪˈsteɪks waɪl ˈspikɪŋ/"},{"start":513.04,"end":518.96,"text":"Native speakers break grammar rules all the time in casual conversation.","words":[["Native",513.04],["speakers",513.52],["break",514.16],["grammar",514.48],["rules",515.12],["all",515.68],["the",515.92],["time",516.24],["in",516.48],["casual",516.8],["conversation.",517.44]],"ipa":"/ˈneɪtɪv ˈspikərz breɪk ˈɡræmər rulz ɔl ðə taɪm ɪn ˈkæʒəwəl ˌkɑnvərˈseɪʃən/"},{"start":518.96,"end":525.84,"text":"They use incomplete sentences, mix tenses, and create new word combinations.","words":[["They",518.96],["use",519.28],["incomplete",519.52],["sentences,",520.32],["mix",521.52],["tenses,",521.92],["and",522.8],["create",523.2],["new",523.6],["word",524],["combinations.",524.32]],"ipa":"/ðeɪ jus ˌɪnkəmˈplit ˈsɛntənsəz mɪks tenses ənd kriˈeɪt nu wɝd ˌkɑmbəˈneɪʃənz/"},{"start":525.84,"end":529.68,"text":"The important thing is that people understand them.","words":[["The",525.84],["important",526.16],["thing",526.64],["is",526.88],["that",527.12],["people",527.52],["understand",528],["them.",528.48]],"ipa":"/ðə ˌɪmˈpɔrtənt θɪŋ ɪz ðæt ˈpipəl ˌʌndərˈstænd ðɛm/"},{"start":529.68,"end":531.92,"text":"The comparison trap.","words":[["The",529.68],["comparison",530],["trap.",530.64]],"ipa":"/ðə kəmˈpɛrəsən træp/"},{"start":531.92,"end":536.96,"text":"The third trap is comparing yourself to other people all the time.","words":[["The",531.92],["third",532.24],["trap",532.56],["is",532.96],["comparing",533.28],["yourself",533.84],["to",534.24],["other",534.56],["people",534.88],["all",535.44],["the",535.6],["time.",535.92]],"ipa":"/ðə θɝd træp ɪz kəmˈpɛrɪŋ jərˈsɛlf tu ˈʌðər ˈpipəl ɔl ðə taɪm/"},{"start":536.96,"end":544.88,"text":"This happens when students constantly look at other English learners and feel bad about their own progress.","words":[["This",536.96],["happens",537.36],["when",537.76],["students",538.24],["constantly",538.88],["look",539.68],["at",539.84],["other",540.08],["English",540.4],["learners",540.88],["and",541.76],["feel",542.08],["bad",542.4],["about",542.72],["their",543.04],["own",543.28],["progress.",543.6]],"ipa":"/ðɪs ˈhæpənz wɛn ˈstudənts ˈkɑnstəntli lʊk æt ˈʌðər ˈɪŋɡlɪʃ ˈlɝnərz ənd fil bæd əˈbaʊt ðɛr oʊn ˈprɑˌɡrɛs/"},{"start":544.88,"end":551.44,"text":"They see someone speaking English well and immediately feel sad about their own abilities.","words":[["They",544.88],["see",545.2],["someone",545.44],["speaking",545.92],["English",546.4],["well",546.96],["and",547.36],["immediately",547.68],["feel",548.48],["sad",548.8],["about",549.2],["their",549.52],["own",549.76],["abilities.",550]],"ipa":"/ðeɪ si ˈsʌmˌwʌn ˈspikɪŋ ˈɪŋɡlɪʃ wɛl ənd ˌɪˈmiˌdiətli fil sæd əˈbaʊt ðɛr oʊn əˈbɪləˌtiz/"},{"start":551.44,"end":557.44,"text":"They forget that everyone starts from a different place and has different goals.","words":[["They",551.44],["forget",551.76],["that",552.16],["everyone",552.48],["starts",553.12],["from",553.44],["a",553.68],["different",553.84],["place",554.08],["and",554.8],["has",555.12],["different",555.44],["goals.",555.76]],"ipa":"/ðeɪ fərˈɡɛt ðæt ˈɛvriˌwʌn stɑrts frʌm ə ˈdɪfərənt pleɪs ənd hæz ˈdɪfərənt ɡoʊlz/"},{"start":557.44,"end":560.96,"text":"Social media makes this trap even worse.","words":[["Social",557.44],["media",557.84],["makes",558.4],["this",558.72],["trap",559.04],["even",559.52],["worse.",559.84]],"ipa":"/ˈsoʊʃəl ˈmidiə meɪks ðɪs træp ˈivɪn wɝs/"},{"start":560.96,"end":566.96,"text":"You see videos of people speaking perfect English and think they learned it very quickly.","words":[["You",560.96],["see",561.2],["videos",561.44],["of",561.84],["people",562.16],["speaking",562.56],["perfect",563.04],["English",563.68],["and",564.16],["think",564.48],["they",564.72],["learned",564.96],["it",565.28],["very",565.44],["quickly.",565.84]],"ipa":"/ju si ˈvɪdioʊz ʌv ˈpipəl ˈspikɪŋ pərˈfɛkt ˈɪŋɡlɪʃ ənd θɪŋk ðeɪ lɝnd ɪt ˈvɛri ˈkwɪkli/"},{"start":566.96,"end":575.36,"text":"You do not see the years of practice, the thousands of mistakes, the times they felt frustrated and wanted to give up.","words":[["You",566.96],["do",567.2],["not",567.36],["see",567.6],["the",567.76],["years",568],["of",568.32],["practice,",568.56],["the",569.44],["thousands",569.76],["of",570.16],["mistakes,",570.4],["the",571.44],["times",571.68],["they",572],["felt",572.32],["frustrated",572.72],["and",573.44],["wanted",573.76],["to",574],["give",574.24],["up.",574.4]],"ipa":"/ju du nɑt si ðə jɪrz ʌv ˈpræktəs ðə ˈθaʊzəndz ʌv mɪˈsteɪks ðə taɪmz ðeɪ fɛlt ˈfrʌˌstreɪtəd ənd ˈwɔntɪd tu ɡɪv ʌp/"},{"start":575.36,"end":581.44,"text":"You only see the final result and it makes your own progress seem small.","words":[["You",575.36],["only",575.6],["see",575.84],["the",576.08],["final",576.4],["result",576.8],["and",577.52],["it",577.76],["makes",577.92],["your",578.16],["own",578.4],["progress",578.72],["seem",579.44],["small.",579.92]],"ipa":"/ju ˈoʊnli si ðə ˈfaɪnəl rɪˈzʌlt ənd ɪt meɪks jɔr oʊn ˈprɑˌɡrɛs sim smɔl/"},{"start":581.44,"end":585.28,"text":"This comparison thinking creates a bad cycle.","words":[["This",581.44],["comparison",581.76],["thinking",582.64],["creates",583.2],["a",583.6],["bad",583.84],["cycle.",584.16]],"ipa":"/ðɪs kəmˈpɛrəsən ˈθɪŋkɪŋ kriˈeɪts ə bæd ˈsaɪkəl/"},{"start":585.28,"end":589.28,"text":"You feel bad about your level, so you lose motivation.","words":[["You",585.28],["feel",585.52],["bad",585.76],["about",586.08],["your",586.32],["level,",586.56],["so",587.04],["you",587.28],["lose",587.52],["motivation.",587.84]],"ipa":"/ju fil bæd əˈbaʊt jɔr ˈlɛvəl soʊ ju luz ˌmoʊtəˈveɪʃən/"},{"start":589.28,"end":594.8,"text":"You study less, practice less, and naturally improve slower.","words":[["You",589.28],["study",589.6],["less,",589.92],["practice",590.72],["less,",591.28],["and",591.84],["naturally",592.16],["improve",592.88],["slower.",593.52]],"ipa":"/ju ˈstʌdi lɛs ˈpræktəs lɛs ənd ˈnætʃərəli ˌɪmˈpruv ˈsloʊər/"},{"start":594.8,"end":600.96,"text":"This makes you believe that you are not good at languages which makes you feel even worse.","words":[["This",594.8],["makes",595.04],["you",595.28],["believe",595.52],["that",595.92],["you",596.16],["are",596.4],["not",596.56],["good",596.8],["at",596.96],["languages",597.2],["which",598.16],["makes",598.48],["you",598.72],["feel",598.96],["even",599.28],["worse.",599.68]],"ipa":"/ðɪs meɪks ju bɪˈliv ðæt ju ɑr nɑt ɡʊd æt ˈlæŋɡwədʒəz wɪtʃ meɪks ju fil ˈivɪn wɝs/"},{"start":600.96,"end":606.8,"text":"Many students give up completely thinking they simply cannot learn English.","words":[["Many",600.96],["students",601.28],["give",601.76],["up",602],["completely",602.32],["thinking",603.28],["they",603.68],["simply",604],["cannot",604.48],["learn",604.96],["English.",605.36]],"ipa":"/ˈmɛni ˈstudənts ɡɪv ʌp kəmˈplitli ˈθɪŋkɪŋ ðeɪ ˈsɪmpli ˈkænɑt lɝn ˈɪŋɡlɪʃ/"},{"start":606.8,"end":610.64,"text":"The truth is that learning English is not a race.","words":[["The",606.8],["truth",607.12],["is",607.44],["that",607.68],["learning",608],["English",608.56],["is",608.96],["not",609.28],["a",609.44],["race.",609.68]],"ipa":"/ðə truθ ɪz ðæt ˈlɝnɪŋ ˈɪŋɡlɪʃ ɪz nɑt ə reɪs/"},{"start":610.64,"end":614.16,"text":"It is a personal journey with its own timing.","words":[["It",610.64],["is",610.88],["a",610.96],["personal",611.2],["journey",611.76],["with",612.16],["its",612.48],["own",612.72],["timing.",613.04]],"ipa":"/ɪt ɪz ə ˈpɝsɪnəl ˈdʒɝni wɪð ɪts oʊn ˈtaɪmɪŋ/"},{"start":614.16,"end":617.36,"text":"Some people have more time to practice.","words":[["Some",614.16],["people",614.48],["have",614.88],["more",615.2],["time",615.52],["to",615.84],["practice.",616.08]],"ipa":"/sʌm ˈpipəl hæv mɔr taɪm tu ˈpræktəs/"},{"start":617.36,"end":620.48,"text":"Some hear English every day at work.","words":[["Some",617.36],["hear",617.68],["English",618.08],["every",618.64],["day",619.04],["at",619.2],["work.",619.52]],"ipa":"/sʌm hir ˈɪŋɡlɪʃ ˈɛvəri deɪ æt wɝk/"},{"start":620.48,"end":623.6,"text":"Some started learning when they were children.","words":[["Some",620.48],["started",620.8],["learning",621.28],["when",621.76],["they",622],["were",622.16],["children.",622.4]],"ipa":"/sʌm ˈstɑrtɪd ˈlɝnɪŋ wɛn ðeɪ wɝ ˈtʃɪldrən/"},{"start":623.6,"end":628.72,"text":"None of this means they are smarter or more talented than you.","words":[["None",623.6],["of",623.92],["this",624.08],["means",624.32],["they",624.64],["are",624.96],["smarter",625.2],["or",625.84],["more",626.24],["talented",626.56],["than",627.12],["you.",627.36]],"ipa":"/nʌn ʌv ðɪs minz ðeɪ ɑr ˈsmɑrtər ɔr mɔr ˈtæləntɪd ðæn ju/"},{"start":628.72,"end":633.92,"text":"Successful learners focus on their own progress, not on other people.","words":[["Successful",628.72],["learners",629.44],["focus",630.08],["on",630.4],["their",630.64],["own",630.88],["progress,",631.2],["not",632.16],["on",632.32],["other",632.56],["people.",632.88]],"ipa":"/səkˈsɛsfəl ˈlɝnərz ˈfoʊkəs ɑn ðɛr oʊn ˈprɑˌɡrɛs nɑt ɑn ˈʌðər ˈpipəl/"},{"start":633.92,"end":636.48,"text":"They celebrate small wins.","words":[["They",633.92],["celebrate",634.24],["small",635.04],["wins.",635.44]],"ipa":"/ðeɪ ˈsɛləˌbreɪt smɔl wɪnz/"},{"start":636.48,"end":639.52,"text":"They track their improvement over time.","words":[["They",636.48],["track",636.72],["their",637.04],["improvement",637.44],["over",638.16],["time.",638.56]],"ipa":"/ðeɪ træk ðɛr ˌɪmˈpruvmənt ˈoʊvər taɪm/"},{"start":639.52,"end":644.32,"text":"They remember where they started and see how far they have come.","words":[["They",639.52],["remember",639.84],["where",640.24],["they",640.48],["started",640.8],["and",641.28],["see",641.6],["how",641.92],["far",642.16],["they",642.56],["have",642.8],["come.",642.96]],"ipa":"/ðeɪ rɪˈmɛmbər wɛr ðeɪ ˈstɑrtɪd ənd si haʊ fɑr ðeɪ hæv kʌm/"},{"start":644.32,"end":646.8,"text":"Make your own success goals.","words":[["Make",644.32],["your",644.56],["own",644.88],["success",645.2],["goals.",645.76]],"ipa":"/meɪk jɔr oʊn səkˈsɛs ɡoʊlz/"},{"start":646.8,"end":650.96,"text":"Maybe it is understanding a movie without subtitles.","words":[["Maybe",646.8],["it",647.12],["is",647.28],["understanding",647.6],["a",648.24],["movie",648.56],["without",648.96],["subtitles.",649.44]],"ipa":"/ˈmeɪbi ɪt ɪz ˌʌndərˈstændɪŋ ə ˈmuvi wɪˈθaʊt ˈsʌbˌtaɪtəlz/"},{"start":650.96,"end":655.12,"text":"Maybe it is having a phone conversation in English.","words":[["Maybe",650.96],["it",651.28],["is",651.52],["having",651.68],["a",652],["phone",652.32],["conversation",652.72],["in",653.52],["English.",653.92]],"ipa":"/ˈmeɪbi ɪt ɪz ˈhævɪŋ ə foʊn ˌkɑnvərˈseɪʃən ɪn ˈɪŋɡlɪʃ/"},{"start":655.12,"end":659.36,"text":"Maybe it is writing an email without using a dictionary.","words":[["Maybe",655.12],["it",655.36],["is",655.52],["writing",655.76],["an",656.08],["email",656.4],["without",656.88],["using",657.44],["a",657.68],["dictionary.",658]],"ipa":"/ˈmeɪbi ɪt ɪz ˈraɪtɪŋ æn iˈmeɪl wɪˈθaʊt ˈjuzɪŋ ə ˈdɪkʃəˌnɛri/"},{"start":659.36,"end":664.8,"text":"Choose goals that are important to you and celebrate when you reach them.","words":[["Choose",659.36],["goals",659.76],["that",660.16],["are",660.48],["important",660.72],["to",661.12],["you",661.36],["and",661.92],["celebrate",662.32],["when",662.88],["you",663.12],["reach",663.28],["them.",663.6]],"ipa":"/tʃuz ɡoʊlz ðæt ɑr ˌɪmˈpɔrtənt tu ju ənd ˈsɛləˌbreɪt wɛn ju ritʃ ðɛm/"},{"start":664.8,"end":666.96,"text":"Keep a progress journal.","words":[["Keep",664.8],["a",665.04],["progress",665.28],["journal.",665.76]],"ipa":"/kip ə ˈprɑˌɡrɛs ˈdʒɝnəl/"},{"start":666.96,"end":674.24,"text":"Write down new words you learn, conversations you have, or moments when you understand something new.","words":[["Write",666.96],["down",667.28],["new",667.68],["words",668],["you",668.24],["learn,",668.56],["conversations",669.28],["you",670.16],["have,",670.4],["or",671.04],["moments",671.36],["when",671.84],["you",672.08],["understand",672.32],["something",672.88],["new.",673.28]],"ipa":"/raɪt daʊn nu wɝdz ju lɝn ˌkɑnvərˈseɪʃənz ju hæv ɔr ˈmoʊmənts wɛn ju ˌʌndərˈstænd ˈsʌmθɪŋ nu/"},{"start":674.24,"end":680.64,"text":"When you feel discouraged, look back at this journal and see how much you have improved.","words":[["When",674.24],["you",674.48],["feel",674.64],["discouraged,",674.96],["look",676.08],["back",676.4],["at",676.64],["this",676.8],["journal",677.04],["and",677.6],["see",677.84],["how",678.16],["much",678.4],["you",678.56],["have",678.8],["improved.",678.96]],"ipa":"/wɛn ju fil dɪˈskɝədʒd lʊk bæk æt ðɪs ˈdʒɝnəl ənd si haʊ mʌtʃ ju hæv ˌɪmˈpruvd/"},{"start":680.64,"end":684.32,"text":"Remember that everyone learns at their own speed.","words":[["Remember",680.64],["that",681.04],["everyone",681.44],["learns",682],["at",682.4],["their",682.72],["own",682.88],["speed.",683.2]],"ipa":"/rɪˈmɛmbər ðæt ˈɛvriˌwʌn lɝnz æt ðɛr oʊn spid/"},{"start":684.32,"end":688.08,"text":"Some people are naturally good at pronunciation.","words":[["Some",684.32],["people",684.64],["are",685.04],["naturally",685.28],["good",685.84],["at",686.16],["pronunciation.",686.4]],"ipa":"/sʌm ˈpipəl ɑr ˈnætʃərəli ɡʊd æt proʊˌnʌnsiˈeɪʃən/"},{"start":688.08,"end":690.4,"text":"Others are better at grammar.","words":[["Others",688.08],["are",688.56],["better",688.8],["at",689.12],["grammar.",689.36]],"ipa":"/ˈʌðərz ɑr ˈbɛtər æt ˈɡræmər/"},{"start":690.4,"end":693.36,"text":"Some learn vocabulary quickly.","words":[["Some",690.4],["learn",690.72],["vocabulary",691.28],["quickly.",692.24]],"ipa":"/sʌm lɝn voʊˈkæbjəˌlɛri ˈkwɪkli/"},{"start":693.36,"end":697.2,"text":"Others are good at understanding native speakers.","words":[["Others",693.36],["are",693.76],["good",694.08],["at",694.32],["understanding",694.56],["native",695.36],["speakers.",695.92]],"ipa":"/ˈʌðərz ɑr ɡʊd æt ˌʌndərˈstændɪŋ ˈneɪtɪv ˈspikərz/"},{"start":697.2,"end":702.16,"text":"Find your strengths and build on them while working on your weak areas.","words":[["Find",697.2],["your",697.52],["strengths",697.76],["and",698.24],["build",698.56],["on",698.8],["them",699.04],["while",699.28],["working",699.6],["on",699.92],["your",700.08],["weak",700.32],["areas.",700.64]],"ipa":"/faɪnd jɔr strɛŋkθs ənd bɪld ɑn ðɛm waɪl ˈwɝkɪŋ ɑn jɔr wik ˈɛriəz/"},{"start":702.16,"end":704.56,"text":"The passive learning trap.","words":[["The",702.16],["passive",702.4],["learning",702.88],["trap.",703.36]],"ipa":"/ðə ˈpæsɪv ˈlɝnɪŋ træp/"},{"start":704.56,"end":708.64,"text":"The fourth and final trap is passive learning.","words":[["The",704.56],["fourth",704.88],["and",705.28],["final",705.6],["trap",706],["is",706.48],["passive",706.88],["learning.",707.44]],"ipa":"/ðə fɔrθ ənd ˈfaɪnəl træp ɪz ˈpæsɪv ˈlɝnɪŋ/"},{"start":708.64,"end":715.28,"text":"This happens when students spend most of their time consuming English content, reading articles,","words":[["This",708.64],["happens",708.96],["when",709.36],["students",709.76],["spend",710.32],["most",710.72],["of",710.96],["their",711.2],["time",711.44],["consuming",712],["English",712.64],["content,",713.12],["reading",713.68],["articles,",714.08]],"ipa":"/ðɪs ˈhæpənz wɛn ˈstudənts spɛnd moʊst ʌv ðɛr taɪm kənˈsumɪŋ ˈɪŋɡlɪʃ ˈkɑntɛnt ˈridɪŋ ˈɑrtəkəlz/"},{"start":715.28,"end":723.12,"text":"watching videos, listening to podcasts without actively practicing speaking or writing.","words":[["watching",715.28],["videos,",715.84],["listening",716.88],["to",717.28],["podcasts",717.6],["without",718.96],["actively",719.52],["practicing",720.24],["speaking",720.96],["or",721.6],["writing.",722]],"ipa":"/ˈwɑtʃɪŋ ˈvɪdioʊz ˈlɪsənɪŋ tu podcasts wɪˈθaʊt ˈæktɪvli ˈpræktəsɪŋ ˈspikɪŋ ɔr ˈraɪtɪŋ/"},{"start":723.12,"end":729.6,"text":"They become good at understanding English but cannot use it fluently when they need to.","words":[["They",723.12],["become",723.44],["good",723.84],["at",724.08],["understanding",724.32],["English",725.12],["but",725.92],["cannot",726.16],["use",726.56],["it",726.8],["fluently",727.12],["when",727.6],["they",727.92],["need",728.08],["to.",728.32]],"ipa":"/ðeɪ bɪˈkʌm ɡʊd æt ˌʌndərˈstændɪŋ ˈɪŋɡlɪʃ bʌt ˈkænɑt jus ɪt ˈfluəntli wɛn ðeɪ nid tu/"},{"start":729.6,"end":733.36,"text":"Passive learning feels comfortable and productive.","words":[["Passive",729.6],["learning",730.08],["feels",730.64],["comfortable",731.2],["and",731.84],["productive.",732.16]],"ipa":"/ˈpæsɪv ˈlɝnɪŋ filz ˈkʌmfərtəbəl ənd prəˈdʌktɪv/"},{"start":733.36,"end":737.12,"text":"You can improve your understanding while sitting on the couch.","words":[["You",733.36],["can",733.6],["improve",733.76],["your",734.16],["understanding",734.4],["while",735.12],["sitting",735.52],["on",735.84],["the",736],["couch.",736.24]],"ipa":"/ju kæn ˌɪmˈpruv jɔr ˌʌndərˈstændɪŋ waɪl ˈsɪtɪŋ ɑn ðə kaʊtʃ/"},{"start":737.12,"end":740.8,"text":"You learn new words naturally through context.","words":[["You",737.12],["learn",737.44],["new",737.68],["words",738],["naturally",738.48],["through",739.04],["context.",739.44]],"ipa":"/ju lɝn nu wɝdz ˈnætʃərəli θru ˈkɑntɛkst/"},{"start":740.8,"end":744.16,"text":"You hear different accents and speaking styles.","words":[["You",740.8],["hear",741.04],["different",741.28],["accents",741.68],["and",742.24],["speaking",742.56],["styles.",743.04]],"ipa":"/ju hir ˈdɪfərənt ˈæksɛnts ənd ˈspikɪŋ staɪlz/"},{"start":744.16,"end":749.76,"text":"But without active practice, these skills only work one way.","words":[["But",744.16],["without",744.32],["active",744.8],["practice,",745.36],["these",746.32],["skills",746.72],["only",747.36],["work",747.76],["one",748.16],["way.",748.48]],"ipa":"/bʌt wɪˈθaʊt ˈæktɪv ˈpræktəs ðiz skɪlz ˈoʊnli wɝk wʌn weɪ/"},{"start":749.76,"end":751.6,"text":"Think about it this way.","words":[["Think",749.76],["about",750.08],["it",750.32],["this",750.56],["way.",750.8]],"ipa":"/θɪŋk əˈbaʊt ɪt ðɪs weɪ/"},{"start":751.6,"end":757.04,"text":"If you wanted to learn to cook, you would not just watch cooking shows for months.","words":[["If",751.6],["you",751.84],["wanted",752],["to",752.24],["learn",752.4],["to",752.64],["cook,",752.88],["you",753.52],["would",753.68],["not",753.84],["just",754.08],["watch",754.4],["cooking",754.8],["shows",755.28],["for",755.76],["months.",756]],"ipa":"/ɪf ju ˈwɔntɪd tu lɝn tu kʊk ju wʊd nɑt dʒʌst wɑtʃ ˈkʊkɪŋ ʃoʊz fɔr mʌnθs/"},{"start":757.04,"end":760.32,"text":"You would need to go to the kitchen and practice.","words":[["You",757.04],["would",757.2],["need",757.44],["to",757.52],["go",757.76],["to",757.84],["the",758.08],["kitchen",758.24],["and",758.64],["practice.",758.96]],"ipa":"/ju wʊd nid tu ɡoʊ tu ðə ˈkɪtʃən ənd ˈpræktəs/"},{"start":760.32,"end":763.52,"text":"The same thing applies to learning English.","words":[["The",760.32],["same",760.64],["thing",760.88],["applies",761.28],["to",761.76],["learning",762.08],["English.",762.48]],"ipa":"/ðə seɪm θɪŋ əˈplaɪz tu ˈlɝnɪŋ ˈɪŋɡlɪʃ/"},{"start":763.52,"end":767.84,"text":"You need to actively use the language to become fluent.","words":[["You",763.52],["need",763.76],["to",763.92],["actively",764.16],["use",764.72],["the",764.96],["language",765.28],["to",765.76],["become",766],["fluent.",766.4]],"ipa":"/ju nid tu ˈæktɪvli jus ðə ˈlæŋɡwədʒ tu bɪˈkʌm ˈfluənt/"},{"start":767.84,"end":772.88,"text":"The best approach combines passive and active learning together.","words":[["The",767.84],["best",768.16],["approach",768.4],["combines",769.04],["passive",769.76],["and",770.32],["active",770.72],["learning",771.2],["together.",771.6]],"ipa":"/ðə bɛst əˈproʊtʃ kəmˈbaɪnz ˈpæsɪv ənd ˈæktɪv ˈlɝnɪŋ təˈɡɛðər/"},{"start":772.88,"end":778.72,"text":"Use passive learning to input new language and improve your understanding.","words":[["Use",772.88],["passive",773.36],["learning",773.84],["to",774.32],["input",774.64],["new",775.04],["language",775.36],["and",776],["improve",776.4],["your",776.8],["understanding.",777.12]],"ipa":"/jus ˈpæsɪv ˈlɝnɪŋ tu ˈɪnˌpʊt nu ˈlæŋɡwədʒ ənd ˌɪmˈpruv jɔr ˌʌndərˈstændɪŋ/"},{"start":778.72,"end":786.16,"text":"Then immediately practice using what you learned through speaking and writing exercises.","words":[["Then",778.72],["immediately",779.2],["practice",780],["using",781.04],["what",781.44],["you",781.68],["learned",781.92],["through",782.32],["speaking",782.72],["and",783.28],["writing",783.68],["exercises.",784.24]],"ipa":"/ðɛn ˌɪˈmiˌdiətli ˈpræktəs ˈjuzɪŋ wʌt ju lɝnd θru ˈspikɪŋ ənd ˈraɪtɪŋ ˈɛksərˌsaɪzəz/"},{"start":786.16,"end":788.32,"text":"Try the echo method.","words":[["Try",786.16],["the",786.4],["echo",786.72],["method.",787.2]],"ipa":"/traɪ ðə ˈɛkoʊ ˈmɛθəd/"},{"start":788.32,"end":796.08,"text":"After watching a video or listening to a podcast, pause and repeat what you heard in your own words.","words":[["After",788.32],["watching",788.72],["a",789.12],["video",789.36],["or",789.76],["listening",790.16],["to",790.56],["a",790.8],["podcast,",791.04],["pause",792.24],["and",792.72],["repeat",793.04],["what",793.52],["you",793.76],["heard",793.92],["in",794.16],["your",794.4],["own",794.64],["words.",794.88]],"ipa":"/ˈæftər ˈwɑtʃɪŋ ə ˈvɪdioʊ ɔr ˈlɪsənɪŋ tu ə ˈpɔdˌkæst pɔz ənd rɪˈpit wʌt ju hɝd ɪn jɔr oʊn wɝdz/"},{"start":796.08,"end":803.92,"text":"This forces you to process the information actively and practice pronunciation at the same time.","words":[["This",796.08],["forces",796.4],["you",796.88],["to",797.12],["process",797.36],["the",797.84],["information",798.16],["actively",798.88],["and",799.76],["practice",800.16],["pronunciation",800.72],["at",801.76],["the",802],["same",802.24],["time.",802.48]],"ipa":"/ðɪs ˈfɔrsɪz ju tu ˈprɑˌsɛs ðə ˌɪnfərˈmeɪʃən ˈæktɪvli ənd ˈpræktəs proʊˌnʌnsiˈeɪʃən æt ðə seɪm taɪm/"},{"start":803.92,"end":806.08,"text":"Use the summary method.","words":[["Use",803.92],["the",804.24],["summary",804.48],["method.",805.04]],"ipa":"/jus ðə ˈsʌməri ˈmɛθəd/"},{"start":806.08,"end":812.96,"text":"After reading an article or watching a video, write a short summary in your own words.","words":[["After",806.08],["reading",806.56],["an",806.96],["article",807.28],["or",807.76],["watching",808.16],["a",808.56],["video,",808.8],["write",809.6],["a",809.92],["short",810.16],["summary",810.56],["in",811.04],["your",811.28],["own",811.52],["words.",811.68]],"ipa":"/ˈæftər ˈridɪŋ æn ˈɑrtəkəl ɔr ˈwɑtʃɪŋ ə ˈvɪdioʊ raɪt ə ʃɔrt ˈsʌməri ɪn jɔr oʊn wɝdz/"},{"start":812.96,"end":820.72,"text":"This helps you practice organizing thoughts in English and using new vocabulary in context.","words":[["This",812.96],["helps",813.28],["you",813.52],["practice",813.84],["organizing",814.4],["thoughts",815.2],["in",815.6],["English",816],["and",816.72],["using",817.04],["new",817.44],["vocabulary",817.76],["in",818.64],["context.",818.96]],"ipa":"/ðɪs hɛlps ju ˈpræktəs ˈɔrɡəˌnaɪzɪŋ θɔts ɪn ˈɪŋɡlɪʃ ənd ˈjuzɪŋ nu voʊˈkæbjəˌlɛri ɪn ˈkɑntɛkst/"},{"start":820.72,"end":823.44,"text":"Create active learning habits.","words":[["Create",820.72],["active",821.2],["learning",821.76],["habits.",822.16]],"ipa":"/kriˈeɪt ˈæktɪv ˈlɝnɪŋ ˈhæbəts/"},{"start":823.44,"end":828,"text":"After every passive learning session, do something active.","words":[["After",823.44],["every",823.92],["passive",824.32],["learning",824.88],["session,",825.28],["do",826.08],["something",826.32],["active.",826.72]],"ipa":"/ˈæftər ˈɛvəri ˈpæsɪv ˈlɝnɪŋ ˈsɛʃən du ˈsʌmθɪŋ ˈæktɪv/"},{"start":828,"end":830.08,"text":"Speak about what you learned.","words":[["Speak",828],["about",828.32],["what",828.64],["you",828.88],["learned.",829.12]],"ipa":"/spik əˈbaʊt wʌt ju lɝnd/"},{"start":830.08,"end":831.92,"text":"Write your opinion about it.","words":[["Write",830.08],["your",830.4],["opinion",830.64],["about",831.04],["it.",831.28]],"ipa":"/raɪt jɔr əˈpɪnjən əˈbaʊt ɪt/"},{"start":831.92,"end":833.92,"text":"Discuss it with someone.","words":[["Discuss",831.92],["it",832.32],["with",832.56],["someone.",832.8]],"ipa":"/dɪˈskʌs ɪt wɪð ˈsʌmˌwʌn/"},{"start":833.92,"end":838.16,"text":"This balance is the key to real improvement.","words":[["This",833.92],["balance",834.24],["is",834.8],["the",835.04],["key",835.28],["to",835.6],["real",835.92],["improvement.",836.32]],"ipa":"/ðɪs ˈbæləns ɪz ðə ki tu ril ˌɪmˈpruvmənt/"},{"start":838.16,"end":840.08,"text":"Try teaching what you learn.","words":[["Try",838.16],["teaching",838.56],["what",839.04],["you",839.28],["learn.",839.44]],"ipa":"/traɪ ˈtitʃɪŋ wʌt ju lɝn/"},{"start":840.08,"end":845.68,"text":"Explain new concepts to a friend or family member in English.","words":[["Explain",840.08],["new",841.04],["concepts",841.36],["to",841.92],["a",842.16],["friend",842.48],["or",842.88],["family",843.28],["member",843.76],["in",844.16],["English.",844.48]],"ipa":"/ɪkˈspleɪn nu ˈkɑnsɛpts tu ə frɛnd ɔr ˈfæməli ˈmɛmbər ɪn ˈɪŋɡlɪʃ/"},{"start":845.68,"end":852.56,"text":"Teaching forces you to organize information clearly and use the language actively.","words":[["Teaching",845.68],["forces",846.24],["you",846.8],["to",847.04],["organize",847.36],["information",848.08],["clearly",848.88],["and",849.68],["use",850],["the",850.24],["language",850.48],["actively.",851.04]],"ipa":"/ˈtitʃɪŋ ˈfɔrsɪz ju tu ˈɔrɡəˌnaɪz ˌɪnfərˈmeɪʃən ˈklɪrli ənd jus ðə ˈlæŋɡwədʒ ˈæktɪvli/"},{"start":852.56,"end":859.36,"text":"Even if the other person does not understand English, the practice is still valuable.","words":[["Even",852.56],["if",852.8],["the",853.04],["other",853.28],["person",853.6],["does",854.08],["not",854.32],["understand",854.64],["English,",855.2],["the",856.08],["practice",856.32],["is",856.88],["still",857.12],["valuable.",857.6]],"ipa":"/ˈivɪn ɪf ðə ˈʌðər ˈpɝsən dʌz nɑt ˌʌndərˈstænd ˈɪŋɡlɪʃ ðə ˈpræktəs ɪz stɪl ˈvæljəbəl/"},{"start":859.36,"end":863.52,"text":"Transform passive activities into active ones.","words":[["Transform",859.36],["passive",860.16],["activities",860.8],["into",861.6],["active",862],["ones.",862.4]],"ipa":"/trænsˈfɔrm ˈpæsɪv ækˈtɪvətiz ˈɪntu ˈæktɪv wʌnz/"},{"start":863.52,"end":869.28,"text":"Instead of just watching movies, repeat interesting phrases out loud.","words":[["Instead",863.52],["of",863.84],["just",864],["watching",864.32],["movies,",864.88],["repeat",865.84],["interesting",866.48],["phrases",867.2],["out",867.84],["loud.",868.08]],"ipa":"/ˌɪnˈstɛd ʌv dʒʌst ˈwɑtʃɪŋ ˈmuviz rɪˈpit ˈɪntrəstɪŋ ˈfreɪzəz aʊt laʊd/"},{"start":869.28,"end":875.04,"text":"Instead of just reading news articles, discuss them with online partners.","words":[["Instead",869.28],["of",869.6],["just",869.76],["reading",870.08],["news",870.48],["articles,",870.88],["discuss",871.84],["them",872.32],["with",872.56],["online",872.96],["partners.",873.6]],"ipa":"/ˌɪnˈstɛd ʌv dʒʌst ˈridɪŋ nuz ˈɑrtəkəlz dɪˈskʌs ðɛm wɪð ˈɔnˌlaɪn ˈpɑrtnərz/"},{"start":875.04,"end":881.68,"text":"Instead of just listening to podcasts, take notes and summarize the main points.","words":[["Instead",875.04],["of",875.44],["just",875.6],["listening",875.92],["to",876.32],["podcasts,",876.64],["take",877.84],["notes",878.16],["and",878.56],["summarize",878.96],["the",879.52],["main",879.84],["points.",880.16]],"ipa":"/ˌɪnˈstɛd ʌv dʒʌst ˈlɪsənɪŋ tu podcasts teɪk noʊts ənd ˈsʌmərˌaɪz ðə meɪn pɔɪnts/"},{"start":881.68,"end":888.8,"text":"In every episode, I love to share a useful phrase that can help your English right away.","words":[["In",881.68],["every",882],["episode,",882.4],["I",883.44],["love",883.76],["to",884],["share",884.24],["a",884.56],["useful",884.8],["phrase",885.36],["that",886],["can",886.24],["help",886.4],["your",886.64],["English",886.88],["right",887.36],["away.",887.6]],"ipa":"/ɪn ˈɛvəri ˈɛpəˌsoʊd aɪ lʌv tu ʃɛr ə ˈjusfəl freɪz ðæt kæn hɛlp jɔr ˈɪŋɡlɪʃ raɪt əˈweɪ/"},{"start":888.8,"end":893.04,"text":"Today's phrase comes from learning and motivation.","words":[["Today's",888.8],["phrase",889.36],["comes",889.92],["from",890.24],["learning",890.56],["and",891.04],["motivation.",891.36]],"ipa":"/təˈdeɪz freɪz kʌmz frʌm ˈlɝnɪŋ ənd ˌmoʊtəˈveɪʃən/"},{"start":893.04,"end":898.56,"text":"Our phrase of the day is practice makes progress, not perfection.","words":[["Our",893.04],["phrase",893.36],["of",893.76],["the",893.92],["day",894.08],["is",894.24],["practice",895.04],["makes",895.52],["progress,",895.92],["not",896.64],["perfection.",896.88]],"ipa":"/ˈaʊər freɪz ʌv ðə deɪ ɪz ˈpræktəs meɪks ˈprɑˌɡrɛs nɑt pərˈfɛkʃən/"},{"start":898.56,"end":903.6,"text":"This phrase reminds us that the goal of practice is not to be perfect,","words":[["This",898.56],["phrase",898.88],["reminds",899.52],["us",899.92],["that",900.16],["the",900.4],["goal",900.64],["of",900.88],["practice",901.12],["is",901.76],["not",902.08],["to",902.32],["be",902.56],["perfect,",902.72]],"ipa":"/ðɪs freɪz riˈmaɪndz ʌs ðæt ðə ɡoʊl ʌv ˈpræktəs ɪz nɑt tu bi pərˈfɛkt/"},{"start":903.6,"end":906.4,"text":"but to get better step by step.","words":[["but",903.6],["to",903.92],["get",904.08],["better",904.32],["step",904.72],["by",905.04],["step.",905.36]],"ipa":"/bʌt tu ɡɛt ˈbɛtər stɛp baɪ stɛp/"},{"start":906.4,"end":910.32,"text":"Each time you practice, you improve a little bit.","words":[["Each",906.4],["time",906.72],["you",907.04],["practice,",907.28],["you",908.16],["improve",908.48],["a",908.88],["little",909.2],["bit.",909.36]],"ipa":"/itʃ taɪm ju ˈpræktəs ju ˌɪmˈpruv ə ˈlɪtəl bɪt/"},{"start":910.32,"end":913.76,"text":"Each mistake teaches you something valuable.","words":[["Each",910.32],["mistake",910.72],["teaches",911.36],["you",911.84],["something",912.08],["valuable.",912.56]],"ipa":"/itʃ mɪˈsteɪk ˈtitʃəz ju ˈsʌmθɪŋ ˈvæljəbəl/"},{"start":913.76,"end":917.52,"text":"Each conversation builds your confidence.","words":[["Each",913.76],["conversation",914.24],["builds",915.2],["your",915.6],["confidence.",915.92]],"ipa":"/itʃ ˌkɑnvərˈseɪʃən bɪldz jɔr ˈkɑnfədəns/"},{"start":917.52,"end":921.84,"text":"You can use this phrase when encouraging yourself or others.","words":[["You",917.52],["can",917.76],["use",917.92],["this",918.16],["phrase",918.48],["when",918.96],["encouraging",919.28],["yourself",919.92],["or",920.4],["others.",920.72]],"ipa":"/ju kæn jus ðɪs freɪz wɛn ɛnˈkɝɪdʒɪŋ jərˈsɛlf ɔr ˈʌðərz/"},{"start":921.84,"end":931.36,"text":"For example, I know my pronunciation is not perfect yet, but I remember that practice makes progress, not perfection.","words":[["For",921.84],["example,",921.92],["I",923.04],["know",923.28],["my",923.52],["pronunciation",923.76],["is",924.64],["not",924.96],["perfect",925.28],["yet,",925.76],["but",926.4],["I",926.64],["remember",926.88],["that",927.28],["practice",927.6],["makes",928.24],["progress,",928.64],["not",929.52],["perfection.",929.84]],"ipa":"/fɔr ɪɡˈzæmpəl aɪ noʊ maɪ proʊˌnʌnsiˈeɪʃən ɪz nɑt pərˈfɛkt jɛt bʌt aɪ rɪˈmɛmbər ðæt ˈpræktəs meɪks ˈprɑˌɡrɛs nɑt pərˈfɛkʃən/"},{"start":931.36,"end":935.92,"text":"Or do not worry about making mistakes in our conversation.","words":[["Or",931.36],["do",931.84],["not",932.08],["worry",932.32],["about",932.64],["making",932.96],["mistakes",933.36],["in",933.92],["our",934.16],["conversation.",934.4]],"ipa":"/ɔr du nɑt ˈwɝi əˈbaʊt ˈmeɪkɪŋ mɪˈsteɪks ɪn ˈaʊər ˌkɑnvərˈseɪʃən/"},{"start":935.92,"end":939.84,"text":"Practice makes progress, not perfection.","words":[["Practice",935.92],["makes",936.56],["progress,",936.96],["not",937.84],["perfection.",938.08]],"ipa":"/ˈpræktəs meɪks ˈprɑˌɡrɛs nɑt pərˈfɛkʃən/"},{"start":939.84,"end":944.56,"text":"Remember this phrase when you feel frustrated with your progress.","words":[["Remember",939.84],["this",940.24],["phrase",940.56],["when",941.2],["you",941.44],["feel",941.6],["frustrated",942],["with",942.72],["your",942.96],["progress.",943.2]],"ipa":"/rɪˈmɛmbər ðɪs freɪz wɛn ju fil ˈfrʌˌstreɪtəd wɪð jɔr ˈprɑˌɡrɛs/"},{"start":944.56,"end":952.16,"text":"Instead of expecting perfection from yourself, focus on the small improvements you make every day.","words":[["Instead",944.56],["of",944.96],["expecting",945.2],["perfection",945.76],["from",946.4],["yourself,",946.64],["focus",947.68],["on",948.16],["the",948.4],["small",948.64],["improvements",949.04],["you",949.68],["make",950],["every",950.32],["day.",950.72]],"ipa":"/ˌɪnˈstɛd ʌv ɪkˈspɛktɪŋ pərˈfɛkʃən frʌm jərˈsɛlf ˈfoʊkəs ɑn ðə smɔl ˌɪmˈpruvmənts ju meɪk ˈɛvəri deɪ/"},{"start":952.16,"end":955.52,"text":"So let us remember what we learned today.","words":[["So",952.16],["let",952.4],["us",952.64],["remember",952.88],["what",953.28],["we",953.52],["learned",953.76],["today.",954.08]],"ipa":"/soʊ lɛt ʌs rɪˈmɛmbər wʌt wi lɝnd təˈdeɪ/"},{"start":955.52,"end":962.64,"text":"First, being afraid to speak keeps you from using English because you worry about making mistakes.","words":[["First,",955.52],["being",956.08],["afraid",956.4],["to",956.72],["speak",956.96],["keeps",957.44],["you",957.76],["from",957.92],["using",958.16],["English",958.64],["because",959.44],["you",959.76],["worry",960.08],["about",960.48],["making",960.88],["mistakes.",961.28]],"ipa":"/fɝst ˈbiɪŋ əˈfreɪd tu spik kips ju frʌm ˈjuzɪŋ ˈɪŋɡlɪʃ bɪˈkɔz ju ˈwɝi əˈbaʊt ˈmeɪkɪŋ mɪˈsteɪks/"},{"start":962.64,"end":971.28,"text":"The solution is to see errors as learning chances and focus on communication, not perfection.","words":[["The",962.64],["solution",962.96],["is",963.44],["to",963.76],["see",964],["errors",964.48],["as",964.96],["learning",965.36],["chances",965.84],["and",966.72],["focus",967.04],["on",967.52],["communication,",967.84],["not",969.2],["perfection.",969.52]],"ipa":"/ðə səˈluʃən ɪz tu si ˈɛrərz æz ˈlɝnɪŋ ˈtʃænsəz ənd ˈfoʊkəs ɑn kəmˌjunəˈkeɪʃən nɑt pərˈfɛkʃən/"},{"start":971.28,"end":980.48,"text":"Second, studying grammar too much can actually slow down your progress by making you think too much about every sentence.","words":[["Second,",971.28],["studying",972],["grammar",972.56],["too",973.12],["much",973.44],["can",973.68],["actually",974.08],["slow",974.56],["down",974.88],["your",975.12],["progress",975.44],["by",976.32],["making",976.64],["you",976.96],["think",977.2],["too",977.52],["much",977.92],["about",978.16],["every",978.56],["sentence.",979.04]],"ipa":"/ˈsɛkənd ˈstʌdiɪŋ ˈɡræmər tu mʌtʃ kæn ˈækˌtʃuəli sloʊ daʊn jɔr ˈprɑˌɡrɛs baɪ ˈmeɪkɪŋ ju θɪŋk tu mʌtʃ əˈbaʊt ˈɛvəri ˈsɛntəns/"},{"start":980.48,"end":987.12,"text":"Learn grammar through real situations and focus on communication patterns.","words":[["Learn",980.48],["grammar",980.88],["through",981.44],["real",981.84],["situations",982.24],["and",983.44],["focus",983.76],["on",984.24],["communication",984.64],["patterns.",985.52]],"ipa":"/lɝn ˈɡræmər θru ril ˌsɪtʃuˈeɪʃənz ənd ˈfoʊkəs ɑn kəmˌjunəˈkeɪʃən ˈpætərnz/"},{"start":987.12,"end":995.44,"text":"Third, comparing yourself to other learners takes away your motivation by making you feel bad about your level.","words":[["Third,",987.12],["comparing",987.92],["yourself",988.48],["to",988.88],["other",989.12],["learners",989.44],["takes",990.08],["away",990.4],["your",990.72],["motivation",990.96],["by",992.16],["making",992.48],["you",992.8],["feel",993.04],["bad",993.36],["about",993.68],["your",994],["level.",994.24]],"ipa":"/θɝd kəmˈpɛrɪŋ jərˈsɛlf tu ˈʌðər ˈlɝnərz teɪks əˈweɪ jɔr ˌmoʊtəˈveɪʃən baɪ ˈmeɪkɪŋ ju fil bæd əˈbaʊt jɔr ˈlɛvəl/"},{"start":995.44,"end":1000.8,"text":"Remember that everyone has their own learning journey and timeline.","words":[["Remember",995.44],["that",995.92],["everyone",996.32],["has",996.96],["their",997.2],["own",997.52],["learning",997.84],["journey",998.4],["and",998.8],["timeline.",999.12]],"ipa":"/rɪˈmɛmbər ðæt ˈɛvriˌwʌn hæz ðɛr oʊn ˈlɝnɪŋ ˈdʒɝni ənd ˈtaɪmlaɪn/"},{"start":1000.8,"end":1004.96,"text":"Fourth, passive learning alone will not make you fluent.","words":[["Fourth,",1000.8],["passive",1001.44],["learning",1001.92],["alone",1002.32],["will",1002.88],["not",1003.2],["make",1003.36],["you",1003.6],["fluent.",1003.84]],"ipa":"/fɔrθ ˈpæsɪv ˈlɝnɪŋ əˈloʊn wɪl nɑt meɪk ju ˈfluənt/"},{"start":1004.96,"end":1012,"text":"You need to balance input with active practice through speaking and writing exercises.","words":[["You",1004.96],["need",1005.2],["to",1005.28],["balance",1005.52],["input",1006],["with",1006.48],["active",1006.8],["practice",1007.36],["through",1008.32],["speaking",1008.72],["and",1009.28],["writing",1009.6],["exercises.",1010.16]],"ipa":"/ju nid tu ˈbæləns ˈɪnˌpʊt wɪð ˈæktɪv ˈpræktəs θru ˈspikɪŋ ənd ˈraɪtɪŋ ˈɛksərˌsaɪzəz/"},{"start":1012,"end":1017.36,"text":"These ideas can change your English learning experience starting today.","words":[["These",1012],["ideas",1012.4],["can",1013.04],["change",1013.36],["your",1013.68],["English",1014],["learning",1014.48],["experience",1014.96],["starting",1015.76],["today.",1016.16]],"ipa":"/ðiz aɪˈdiəz kæn tʃeɪndʒ jɔr ˈɪŋɡlɪʃ ˈlɝnɪŋ ɪkˈspɪriəns ˈstɑrtɪŋ təˈdeɪ/"},{"start":1017.36,"end":1023.68,"text":"Choose one trap that sounds familiar to you and promise to avoid it this week.","words":[["Choose",1017.36],["one",1017.76],["trap",1018.16],["that",1018.64],["sounds",1019.04],["familiar",1019.44],["to",1019.92],["you",1020.16],["and",1020.64],["promise",1020.96],["to",1021.44],["avoid",1021.68],["it",1022.08],["this",1022.32],["week.",1022.56]],"ipa":"/tʃuz wʌn træp ðæt saʊndz fəˈmɪljər tu ju ənd ˈprɑməs tu əˈvɔɪd ɪt ðɪs wik/"},{"start":1023.68,"end":1028.32,"text":"Notice how this change affects your confidence and progress.","words":[["Notice",1023.68],["how",1024.08],["this",1024.4],["change",1024.72],["affects",1025.12],["your",1025.6],["confidence",1025.92],["and",1026.48],["progress.",1026.88]],"ipa":"/ˈnoʊtəs haʊ ðɪs tʃeɪndʒ əˈfɛkts jɔr ˈkɑnfədəns ənd ˈprɑˌɡrɛs/"},{"start":1028.32,"end":1040.24,"text":"If this episode helped you understand your learning problems better, please give it a thumbs up and share it with other English learners who might benefit from these ideas.","words":[["If",1028.32],["this",1028.64],["episode",1028.96],["helped",1029.52],["you",1029.84],["understand",1030.08],["your",1030.56],["learning",1030.88],["problems",1031.2],["better,",1031.84],["please",1032.8],["give",1033.12],["it",1033.28],["a",1033.52],["thumbs",1033.68],["up",1033.92],["and",1034.48],["share",1034.88],["it",1035.12],["with",1035.36],["other",1035.6],["English",1036],["learners",1036.4],["who",1037.12],["might",1037.44],["benefit",1037.76],["from",1038.24],["these",1038.48],["ideas.",1038.88]],"ipa":"/ɪf ðɪs ˈɛpəˌsoʊd hɛlpt ju ˌʌndərˈstænd jɔr ˈlɝnɪŋ ˈprɑbləmz ˈbɛtər pliz ɡɪv ɪt ə θʌmz ʌp ənd ʃɛr ɪt wɪð ˈʌðər ˈɪŋɡlɪʃ ˈlɝnərz hu maɪt ˈbɛnəfɪt frʌm ðiz aɪˈdiəz/"},{"start":1040.24,"end":1048,"text":"Your support helps us create more content that makes a real difference in your language learning journey.","words":[["Your",1040.24],["support",1040.56],["helps",1041.12],["us",1041.44],["create",1041.84],["more",1042.24],["content",1042.64],["that",1043.6],["makes",1043.92],["a",1044.16],["real",1044.4],["difference",1044.72],["in",1045.12],["your",1045.44],["language",1045.6],["learning",1046.16],["journey.",1046.56]],"ipa":"/jɔr səˈpɔrt hɛlps ʌs kriˈeɪt mɔr ˈkɑntɛnt ðæt meɪks ə ril ˈdɪfərəns ɪn jɔr ˈlæŋɡwədʒ ˈlɝnɪŋ ˈdʒɝni/"},{"start":1048,"end":1055.92,"text":"Do not forget to subscribe to Coffee English for more practical tips and methods that actually work.","words":[["Do",1048],["not",1048.24],["forget",1048.48],["to",1048.8],["subscribe",1049.04],["to",1049.68],["Coffee",1049.92],["English",1050.56],["for",1051.12],["more",1051.36],["practical",1051.68],["tips",1052.32],["and",1052.72],["methods",1053.04],["that",1054],["actually",1054.4],["work.",1054.88]],"ipa":"/du nɑt fərˈɡɛt tu səbˈskraɪb tu ˈkɑfi ˈɪŋɡlɪʃ fɔr mɔr ˈpræktəkəl tɪps ənd ˈmɛθədz ðæt ˈækˌtʃuəli wɝk/"},{"start":1055.92,"end":1061.36,"text":"We are here to support you every step of the way to English fluency.","words":[["We",1055.92],["are",1056.16],["here",1056.32],["to",1056.56],["support",1056.8],["you",1057.12],["every",1057.6],["step",1058],["of",1058.24],["the",1058.48],["way",1058.64],["to",1058.88],["English",1059.2],["fluency.",1059.6]],"ipa":"/wi ɑr hir tu səˈpɔrt ju ˈɛvəri stɛp ʌv ðə weɪ tu ˈɪŋɡlɪʃ ˈfluənsi/"},{"start":1061.36,"end":1067.44,"text":"Thank you for joining me on this journey through the common mistakes of English learning.","words":[["Thank",1061.36],["you",1061.6],["for",1061.84],["joining",1062.08],["me",1062.48],["on",1062.72],["this",1062.96],["journey",1063.2],["through",1063.76],["the",1064.08],["common",1064.32],["mistakes",1064.72],["of",1065.28],["English",1065.6],["learning.",1066.08]],"ipa":"/θæŋk ju fɔr ˈdʒɔɪnɪŋ mi ɑn ðɪs ˈdʒɝni θru ðə ˈkɑmən mɪˈsteɪks ʌv ˈɪŋɡlɪʃ ˈlɝnɪŋ/"},{"start":1067.44,"end":1073.12,"text":"Remember, knowing about these problems is the first step to fixing them.","words":[["Remember,",1067.44],["knowing",1068.4],["about",1068.8],["these",1069.12],["problems",1069.52],["is",1070.16],["the",1070.4],["first",1070.72],["step",1070.96],["to",1071.28],["fixing",1071.6],["them.",1072]],"ipa":"/rɪˈmɛmbər ˈnoʊɪŋ əˈbaʊt ðiz ˈprɑbləmz ɪz ðə fɝst stɛp tu ˈfɪksɪŋ ðɛm/"},{"start":1073.12,"end":1079.36,"text":"Now that you know what to avoid, you can focus your energy on what actually works.","words":[["Now",1073.12],["that",1073.36],["you",1073.6],["know",1073.76],["what",1074],["to",1074.16],["avoid,",1074.4],["you",1075.28],["can",1075.52],["focus",1075.68],["your",1076.08],["energy",1076.4],["on",1076.96],["what",1077.28],["actually",1077.6],["works.",1078]],"ipa":"/naʊ ðæt ju noʊ wʌt tu əˈvɔɪd ju kæn ˈfoʊkəs jɔr ˈɛnərdʒi ɑn wʌt ˈækˌtʃuəli wɝks/"},{"start":1079.36,"end":1085.76,"text":"Until next time, keep practicing, keep improving, and keep believing in yourself.","words":[["Until",1079.36],["next",1079.84],["time,",1080.16],["keep",1080.8],["practicing,",1081.2],["keep",1082.32],["improving,",1082.56],["and",1083.36],["keep",1083.6],["believing",1083.92],["in",1084.32],["yourself.",1084.56]],"ipa":"/ənˈtɪl nɛkst taɪm kip ˈpræktəsɪŋ kip ˌɪmˈpruvɪŋ ənd kip bɪˈlivɪŋ ɪn jərˈsɛlf/"},{"start":1085.76,"end":1089.44,"text":"Your English fluency is closer than you think.","words":[["Your",1085.76],["English",1086],["fluency",1086.4],["is",1086.96],["closer",1087.36],["than",1087.76],["you",1087.92],["think.",1088.16]],"ipa":"/jɔr ˈɪŋɡlɪʃ ˈfluənsi ɪz ˈkloʊsər ðæn ju θɪŋk/"},{"start":1089.44,"end":1091.68,"text":"This has been Coffee English.","words":[["This",1089.44],["has",1089.68],["been",1089.92],["Coffee",1090.16],["English.",1090.72]],"ipa":"/ðɪs hæz bɪn ˈkɑfi ˈɪŋɡlɪʃ/"},{"start":1091.68,"end":1109.55,"text":"See you in the next episode.","words":[["See",1091.68],["you",1091.92],["in",1092.08],["the",1092.24],["next",1092.4],["episode.",1092.72]],"ipa":"/si ju ɪn ðə nɛkst ˈɛpəˌsoʊd/"}]`),i=[{level:"B2",group:"Kinh nghiệm học tập",order:32}],h={id:t,youtubeId:e,title:s,channel:n,level:"B1",group:r,order:16,duration:1108,captions:a,segments:o,also:i};export{i as also,a as captions,n as channel,h as default,u as duration,r as group,t as id,d as level,l as order,o as segments,s as title,e as youtubeId};
